/**
 * dsh-notifier pipeline 域 —— 裁决：这条通知现在该不该发（唯一裁决点，别处不许再判）。
 * 判据不实现为抛错：本块挂在活的调用链上。
 */
import type { EffectiveConfig } from "../../deps.ts";
import { KIND_SWITCHES, inWindowMinutes } from "../../../../shared/interface.ts";
import { isBuiltinKind } from "../service/kinds.ts";
import type { BuiltinKind, NotifyKind } from "../service/kinds.ts";
import type { NotifyRequest } from "../service/type.ts";
import type { SuppressReason, Verdict } from "./type.ts";

/**
 * 单个窗口是否命中（纯函数：只看分钟数与起止，不读当前时间，方便逐分钟单测）。
 *
 * 事实源在 src/shared/quiet.ts（`inWindowMinutes`）：客户端本机回显与服务端裁决同源，
 * 改动只改共享处。这里保留名字，兼容既有 `judge/index.ts` 引用面与单测表驱动。
 */
export function inWindow(minutes: number, start: string, end: string): boolean {
  return inWindowMinutes(minutes, start, end);
}

/** 是否落在免打扰时段内：命中任一窗口即压制（并集语义）；空数组等于未命中。
 *
 * 单项逐个收窄：脏项（非对象、start/end 非字符串）按未命中跳过，不抛——本块挂在活的
 * 调用链上，判据不实现为抛错（见文件头）。 */
function isQuietNow(now: Date, quietHours: EffectiveConfig["quietHours"]): boolean {
  if (quietHours.enabled !== true) return false;
  const minutes = now.getHours() * 60 + now.getMinutes();
  const windows = Array.isArray(quietHours.windows) ? quietHours.windows : [];
  return windows.some((window) => {
    if (typeof window !== "object" || window === null || Array.isArray(window)) return false;
    const start = (window as { start?: unknown }).start;
    const end = (window as { end?: unknown }).end;
    if (typeof start !== "string" || typeof end !== "string") return false;
    return inWindow(minutes, start, end);
  });
}

/**
 * 裁决。判据顺序即短路顺序：**总开关 → kind 开关 → 动态 kind 确认 → 免打扰**。
 *
 * 每条规则写成一个有名函数、顺序在这四行里读得出来：此前四条规则混在一个函数体里、
 * 「`test` 不受约束」这个例外散在三处判断里，想插一条规则的人只能从中间猜位置。
 */
export function judgeRequest(
  config: EffectiveConfig,
  request: NotifyRequest,
  enabled: boolean,
): Verdict {
  const kind = request.kind;
  if (enabled === false) return blocked("disabled");
  // `test` 是用户主动按下的自检：过了总开关就不再受 kind 开关与免打扰约束——被静音吃掉
  // 等于测试按钮失效，而它验证的正是链路本身。这一句也是 `test` 在全文件唯一的例外。
  if (kind === "test") return passed();
  if (isBuiltinKind(kind) && isKindOff(config, kind)) return blocked("kind-off");
  if (isUnconfirmed(config, kind)) return blocked("unlisted");
  if (isQuietNow(new Date(), config.quietHours) && !allowsInQuiet(config.quietHours, kind)) {
    return blocked("quiet");
  }
  return passed();
}

/** 内置 kind 看它自己的事件开关（`test` 没有开关，调用方在此之前已放行它）。 */
function isKindOff(config: EffectiveConfig, kind: Exclude<BuiltinKind, "test">): boolean {
  return config[KIND_SWITCHES[kind]] !== true;
}

/** 外部注册的 kind 没有开关这一关，只认用户是否确认过（确认态的物理形态就是 allowKinds）。 */
function isUnconfirmed(config: EffectiveConfig, kind: NotifyKind): boolean {
  return !isBuiltinKind(kind) && !config.allowKinds.includes(kind);
}

/** 免打扰时段内放行谁：只有被显式写进 `allowKinds` 的 kind 能穿过去。 */
function allowsInQuiet(quietHours: EffectiveConfig["quietHours"], kind: NotifyKind): boolean {
  const allowed = quietHours.allowKinds ?? [];
  return allowed.includes(kind);
}

function passed(): Verdict {
  return { ok: true };
}

/** 压制：原因随记录写进历史，是「为什么我没收到」的唯一答案来源。 */
function blocked(reason: SuppressReason): Verdict {
  return { ok: false, reason };
}

/**
 * dsh-notifier pipeline 域 —— 路由：这条通知该发给谁（纯函数，判据全来自设置）。
 * 目标身份由客户端锁定：`bark:<id>` / `webhook:<id>` / 内置 `browser`、`system`。
 *
 * 本块对每个频道**只有一个判断：`enabled`**（发不发）。发什么——弹窗、声音、只响不弹、还是什么都
 * 不发——由出口按传到手上的配置自己决定；管线只搬配置，不预设形态。
 */
import type { EffectiveConfig } from "../../deps.ts";
import { BUILTIN_CHANNELS, channelIdOf, deliveryPresetOf } from "../../../../shared/interface.ts";
import { toastScriptPath } from "../../../shared/interface.ts";
import type { NotifyKind } from "../service/kinds.ts";
import type { NotifyRequest } from "../service/type.ts";
import type {
  BarkConfig,
  BarkTarget,
  BarkTextKey,
  BrowserConfig,
  RouteDeps,
  RouteOutcome,
  RoutedTarget,
  SystemConfig,
  WebhookConfig,
  WebhookTarget,
} from "./type.ts";

// 内置频道 id、频道对外 id 规则与「配置层预设 → 投递层预设」的改名都是两端契约，事实源在
// src/shared/{channels,webhooks}.ts（客户端消费同一份）：两端各写一份时的漂移症状是「用户勾了
// 频道却收不到」与「设置页看到的模板不是实际发出去的那份」。

/** 路由：按 kind 与设置选出本次要投递的目标。 */
export function routeTargets(
  deps: RouteDeps,
  config: EffectiveConfig,
  request: NotifyRequest,
): RouteOutcome {
  return narrowRoutes(config, request, resolvePool(deps, config, request.kind));
}

/**
 * 投递池：本次请求可用的全部目标（路由收窄之前的全集），顺序即 `channels` 顺序（内置恒在最前）。
 *
 * 唯一的判据是 `enabled`：弹窗与声音都关掉的频道照样进池，由出口回答「这次没有可发的内容」
 * ——那既不是在这里替出口判形态，也不会被伪装成一次投递成功。
 *
 * 整段包在 try 里：读配置 fail-soft，一个脏项不该吃掉整条通知（配置坏与出口失败是两回事——
 * 后者是返回值，前者只能在这里拦住）。已收进池的目标照常投递。
 */
function resolvePool(deps: RouteDeps, config: EffectiveConfig, kind: NotifyKind): RoutedTarget[] {
  const pool: RoutedTarget[] = [];
  try {
    for (const channel of config.channels) {
      if (!channel.enabled) continue;
      switch (channel.type) {
        case "browser":
          pool.push(browserTarget(channel, deps, kind));
          break;
        case "system":
          pool.push(systemTarget(channel, deps));
          break;
        case "bark":
          pool.push({ channelId: channelIdOf(channel), target: barkTarget(channel, kind) });
          break;
        case "webhook":
          pool.push({ channelId: channelIdOf(channel), target: webhookTarget(channel) });
          break;
      }
    }
  } catch (cause) {
    deps.logger.warn(
      `dsh-notifier: 频道读取失败（fail-soft 跳过）: ${cause instanceof Error ? cause.message : String(cause)}`,
    );
  }
  return pool;
}

/** 浏览器内置频道 → 目标：配置原样搬运，播放决议由出口解析。
 *
 * 导出给草稿测试（dry-run）复用同一份映射：它跳过 enabled 门直构单目标，映射本身必须与
 * 路由一致，否则「测得通、存下来不通」。 */
export function browserTarget(
  channel: BrowserConfig,
  deps: RouteDeps,
  kind: NotifyKind,
): RoutedTarget {
  return {
    channelId: BUILTIN_CHANNELS.browser,
    target: {
      type: "browser",
      popup: channel.popup,
      sound: channel.sound,
      whenVisible: channel.whenVisible,
      // kind 随帧一起出去：客户端靠它选图标与颜色。
      emitFrame: (frame) => deps.frames.emit({ kind, frame }),
    },
  };
}

/** 系统内置频道 → 目标；脚本路径由组合层推导后传入，出口不做路径猜测。
 *
 * 导出理由同 browserTarget：dry-run 直构单目标时复用同一份映射。 */
export function systemTarget(channel: SystemConfig, deps: RouteDeps): RoutedTarget {
  return {
    channelId: BUILTIN_CHANNELS.system,
    target: {
      type: "system",
      popup: channel.popup,
      sound: channel.sound,
      toastScript: toastScriptPath(),
      logger: deps.logger,
    },
  };
}

/** bark 配置 → 投递参数；空串是归一化表达「没配置」，投递层的缺省才是真缺省。
 *
 * 导出理由同 browserTarget：dry-run 直构单目标时复用同一份映射。 */
export function barkTarget(channel: BarkConfig, kind: NotifyKind): BarkTarget {
  const target: BarkTarget = {
    type: "bark",
    baseUrl: channel.baseUrl,
    deviceKey: channel.deviceKey,
  };
  const level = channel.levels?.[kind] ?? channel.level;
  assignText(target, "level", level ?? "");
  assignText(target, "group", channel.group ?? "");
  assignText(target, "sound", channel.sound ?? "");
  assignText(target, "icon", channel.icon ?? "");
  assignText(target, "url", channel.url ?? "");
  // badge 是数字（0 有语义：清掉角标），所以「有值就带」而不是「非零才带」。
  if (channel.badge !== undefined) target.badge = channel.badge;
  if (channel.timeoutMs !== undefined && channel.timeoutMs > 0) {
    target.timeoutMs = channel.timeoutMs;
  }
  // 未知键整袋带走：出口把它原样写进推送体（前向兼容），这里不做逐键判断。
  if (channel.extras !== undefined) target.extras = channel.extras;
  return target;
}

/** 可选文本字段：空串即「没配置」，不带进目标。 */
function assignText(target: BarkTarget, key: BarkTextKey, value: string): void {
  if (value.length > 0) target[key] = value;
}

/** webhook 配置 → 投递参数；凭据在这里解析成投递层的对象。
 *
 * 导出理由同 browserTarget：dry-run 直构单目标时复用同一份映射。 */
export function webhookTarget(channel: WebhookConfig): WebhookTarget {
  const target: WebhookTarget = {
    type: "webhook",
    url: channel.url,
    preset: presetOf(channel),
  };
  // 自定义模板留空即用预设默认模板，所以空串不带进目标。
  if (channel.template !== undefined && channel.template.length > 0) {
    target.template = channel.template;
  }
  // 自定义头先落配置里的那份，认证头随后并入：同名时认证头是更强的事实。
  const headers = { ...channel.headers };
  assignAuth(target, channel);
  assignAuthHeader(headers, channel);
  if (Object.keys(headers).length > 0) target.headers = headers;
  if (channel.timeoutSec !== undefined && channel.timeoutSec > 0) {
    target.timeoutSec = channel.timeoutSec;
  }
  // 未知键只保留在生效设置里（webhook 的 body 由模板渲染，透传键不绕开模板语义）。
  if (channel.extras !== undefined) target.extras = channel.extras;
  return target;
}

/** bearer / basic 凭据写进目标；空串与缺省同义（都没配），此时不带认证。 */
function assignAuth(target: WebhookTarget, channel: WebhookConfig): void {
  if (channel.auth === "bearer" && channel.token !== undefined && channel.token.length > 0) {
    target.auth = { kind: "bearer", token: channel.token };
    return;
  }
  if (channel.auth === "basic" && channel.username !== undefined && channel.username.length > 0) {
    target.auth = { kind: "basic", user: channel.username, password: channel.password ?? "" };
  }
}

/** header 认证的头并入自定义头；名或值为空即没配全，与「认证方式不是 header」一样不带。 */
function assignAuthHeader(headers: Record<string, string>, channel: WebhookConfig): void {
  if (channel.auth !== "header") return;
  const name = channel.headerName;
  const value = channel.headerValue;
  if (name !== undefined && name.length > 0 && value !== undefined && value.length > 0) {
    headers[name] = value;
  }
}

/** 缺 preset 回落 `ntfy`：归一化后恒有值，这里是脏配置的兜底（与旧实现同口径）。 */
function presetOf(channel: WebhookConfig): WebhookTarget["preset"] {
  const preset = channel.preset;
  return preset === undefined ? "ntfy" : deliveryPresetOf(preset);
}

/**
 * 路由裁决：`onlyChannel` 直接命中一处并绕过 `kindRoutes`；`kindRoutes[kind]` 非空则把
 * 结果收窄到命中的 id；空或缺省 = 广播全部启用频道。
 */
function narrowRoutes(
  config: EffectiveConfig,
  request: NotifyRequest,
  pool: RoutedTarget[],
): RouteOutcome {
  const only = request.onlyChannel;
  if (only !== undefined) return { targets: pool.filter((t) => t.channelId === only), stale: [] };
  const routes: string[] = config.kindRoutes[request.kind] ?? [];
  if (routes.length === 0) return { targets: pool, stale: [] };
  const wanted = new Set(routes);
  // 停用不算「已删除」：旧实现只对配置里根本不存在的 id 报 stale，否则用户一停用频道
  // 就会收到一串「指向已删除频道」的误导告警。
  const known = knownChannelIds(config);
  return {
    targets: pool.filter((t) => wanted.has(t.channelId)),
    stale: routes.filter((id) => !known.has(id)),
  };
}

/** 已存在的频道 id：内置两个 + 配置里的全部实例（含停用的）。 */
function knownChannelIds(config: EffectiveConfig): Set<string> {
  const known = new Set<string>();
  // 内置条目与实例走同一条 id 规则（`channelIdOf` 对内置取裸 `type`），这里不为它们开分支：
  // 归一化保证两条内置条目恒在场，所以 `browser` / `system` 一定被收进来。
  for (const channel of config.channels) known.add(channelIdOf(channel));
  return known;
}

/**
 * dsh-notifier pipeline 域 —— 编排：一条通知从「发生」到「出去」的全程。
 * 本块只串流程，另做一件事是归档——记录这条通知走到了哪一步、为什么没走完。
 */
import type { ChannelDelivery, HistoryEntry, PipelineDeps, StorePort } from "../../deps.ts";
import { notificationDispatcher } from "../dispatch/index.ts";
import { finalizeRequest } from "../finalize/index.ts";
import { judgeRequest } from "../judge/index.ts";
import type { SuppressReason } from "../judge/type.ts";
import { routeTargets } from "../route/index.ts";
import type { RoutedTarget } from "../route/type.ts";
import type { NotifyRequest } from "./type.ts";

/** 归档结果：发出去了带逐出口明细，被压制了带原因；两者必居其一。 */
type ArchiveOutcome = { suppressed: SuppressReason } | { channels: ChannelDelivery[] };

/** 未装配的告警文案：占位能力被真的读到，说明装配守卫有洞。 */
const NOT_INSTALLED = "dsh-notifier: 裁决管线尚未装配";

/**
 * 未装配时的占位：让字段有确定的类型，不必让每个使用点先判一次空。
 * 能力占位成抛错而不是空实现——真被读到时「没装配」应当当场暴露。帧出口是例外：它是
 * 旁路，「没人听」与「没有出口」对它没有区别。
 */
const UNINSTALLED: PipelineDeps = {
  enabled: false,
  frames: { emit: () => {} },
  logger: { warn: () => {} },
  config: {
    readConfig: () => {
      throw new Error(NOT_INSTALLED);
    },
  },
  stores: {
    appendHistory: () => {
      throw new Error(NOT_INSTALLED);
    },
    recordStatus: () => {
      throw new Error(NOT_INSTALLED);
    },
  },
  channels: {
    deliver: () => Promise.reject(new Error(NOT_INSTALLED)),
  },
};

/** 裁决管线：唯一裁决点，以及一条通知的生命周期。 */
class NotificationPipeline {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  /** 装配入参：宿主能力、挂载点值，以及本域依赖的那几个域。 */
  private deps: PipelineDeps = UNINSTALLED;

  /** 装配。重复装配是编程错误，当场暴露。 */
  install(deps: PipelineDeps): void {
    if (this.installed) throw new Error("dsh-notifier: pipeline 域只能装配一次");
    this.installed = true;
    this.deps = deps;
    notificationDispatcher.install({ channels: deps.channels, stores: deps.stores });
  }

  /** 卸载：清空投递节奏状态、放开对宿主面的引用。此后到达的请求一律丢弃。 */
  release(): void {
    this.installed = false;
    this.deps = UNINSTALLED;
    notificationDispatcher.release();
  }

  /**
   * 提交一条通知请求。
   * 未装配时静默丢弃，不抛错：本方法挂在宿主事件链上，在这里抛会打断别人的流程。
   */
  submit(request: NotifyRequest): void {
    if (!this.installed) return;
    // 能力在入口取一次并往下传：`send` 是异步的，卸载可能发生在它完成之前，而这次
    // 投递已经开始了——半路换成占位值会让一条本该正常送达的通知凭空失败。
    const { enabled, frames, logger, config, stores } = this.deps;
    // 本次通知的时刻只取一次：投递载荷与历史记录共用它，两处各取一次会对不上。
    const ts = Date.now();

    const snapshot = config.readConfig();
    const verdict = judgeRequest(snapshot, request, enabled);
    if (!verdict.ok) {
      this.archive(stores, request, ts, { suppressed: verdict.reason });
      return;
    }

    const route = routeTargets({ frames, logger }, snapshot, request);
    const noTargets = route.targets.length === 0;
    for (const id of route.stale) {
      // 归档只认 `SuppressReason` 的词表：日志按同一口径说这条路由项的去向，不另造归档里查不到的词。
      const fate = noTargets
        ? "本条通知归档 suppressed:no-target"
        : "该目标已丢弃，其余目标照常投递";
      logger.warn(`dsh-notifier: kindRoutes[${request.kind}] 指向已删除频道 ${id}，${fate}`);
    }
    if (noTargets) {
      this.archive(stores, request, ts, { suppressed: "no-target" });
      return;
    }

    void this.send(stores, request, ts, route.targets).catch((cause) => {
      // 投递块承诺逐目标 fail-soft（失败是返回值，不是异常），走到这里说明契约已被破坏。
      // 宿主事件链上不能抛，但也不能静默——「通知没发出去、且没有任何痕迹」最难查。
      const reason = cause instanceof Error ? cause.message : String(cause);
      logger.warn(`dsh-notifier: 投递失败 —— ${reason}`);
    });
  }

  /** 定稿，投递，归档。 */
  private async send(
    stores: StorePort,
    request: NotifyRequest,
    ts: number,
    targets: RoutedTarget[],
  ): Promise<void> {
    const message = finalizeRequest(request, ts);
    const deliveries = await notificationDispatcher.dispatch(message, targets);
    this.archive(stores, request, ts, { channels: deliveries });
  }

  /** 归档：一次通知写一条记录，发出与压制只在载荷上分叉。 */
  private archive(
    stores: StorePort,
    request: NotifyRequest,
    ts: number,
    outcome: ArchiveOutcome,
  ): void {
    const entry: HistoryEntry = {
      ts,
      kind: request.kind,
      title: request.title,
      message: request.body,
    };
    if ("suppressed" in outcome) {
      entry.suppressed = outcome.suppressed;
    } else {
      entry.channels = outcome.channels;
    }
    stores.appendHistory(entry);
  }
}

/** 本域唯一的裁决点：类不外放，外面 `new` 不出第二份。 */
export const notificationPipeline = new NotificationPipeline();

packages/dsh-notifier/test/integration/r.source:
/**
 * dsh-notifier — 组合根（`src/index.ts`）的真实 cordis Context 集成测试。
 *
 * 面口径：这里测的是**宿主看见的那一面**——`apply` 收窄宿主上下文、按序装配八个域、卸载逆序释放。
 * 这些行为只有放进真实 cordis 才成立：`inject` 门（未就绪不装配）、两条 waterfall 的 `prepend`
 * 链序、`{ global: true }` 的作用域过滤、`ctx.effect` 的卸载时机、`internal/service` 的晚到通知。
 * 假宿主只提供 `webServer`（组合根唯一触碰的宿主服务）与可选的 `settings`；事件总线、落盘、
 * 裁决管线全是真的——**不 mock `@deepseek-ai/cordis`**，也不用 `vi.mock`/`vi.fn`。
 *
 * 落盘隔离（红线）：config / stores / stream 的单例在**模块加载期**就用 `notifierFile()` 定死了
 * 路径，所以必须先把 `DSH_HOME` 指到 `mkdtempSync` 出的临时目录，再用**动态 `import()`** 拉组合根。
 * 写反了本节全部落盘就进真实 `~/.dsh`——那正是正在跑的 `dsh web` 的 home。
 *
 * 写队列纪律：历史与配置的落盘是 fire-and-forget（写队列是模块级字段，`release` 不清它），故每个
 * 产生落盘的用例都要等到自己那一条在磁盘上可见才算完；需要「没有新写入」这类否定判据时，用
 * `stores` 域自己的写口排一次队当**界碑**——队列串行，界碑落盘即此前排队的全部落盘。
 *
 * 时间纪律：本文件不钉系统时钟，`pollUntil` 的 deadline 读的正是 `Date.now()`，钉住它失败会从
 * 「断言红」退化成挂死。`afterEach` 仍还原一次，防将来有人在用例里钉。
 */
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { Context } from "@deepseek-ai/cordis";
import type { Events, Fiber, ThisType as EventThis } from "@deepseek-ai/cordis";
import type { Agent } from "@deepseek-ai/dsh-agent";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import type { Session, SessionEvent } from "@deepseek-ai/dsh-session";
import type { ApprovalOutcome, ApprovalRequest } from "@deepseek-ai/dsh-user-approval";
import type {
  AskUserQuestionAnswer,
  AskUserQuestionRequest,
} from "@deepseek-ai/dsh-user-questions";

import {
  assertEventReachability,
  assertRealCordisContextSemantics,
} from "../../../../test/smoke-lib.ts";
import { pollUntil, settleMicrotasks, tempDshHome } from "../helpers.ts";

// DSH_HOME 必须先于被测模块求值：三个单例的落盘路径在构造时定下，而静态 import 会在任何语句
// 之前执行——顺序反了，本节全部落盘就写进真实 `~/.dsh`。
const home = tempDshHome();
const notifier = await import("../../src/index.ts");
const apiApi = await import("../../src/server/api/interface.ts");
const configApi = await import("../../src/server/config/interface.ts");
const sdkApi = await import("../../src/server/sdk/interface.ts");
const storesApi = await import("../../src/server/stores/interface.ts");
const sharedApi = await import("../../src/server/shared/interface.ts");

/** 本插件的落盘位置（新布局：包私有目录，见 `shared/paths.ts`）。 */
const storageDir = join(home.dir, "@wingsky-1", "dsh-notifier");
const configFile = sharedApi.notifierFile(sharedApi.CONFIG_FILE_NAME);
const historyFile = sharedApi.notifierFile(sharedApi.HISTORY_FILE_NAME);
const seqFile = sharedApi.notifierFile(sharedApi.SEQ_FILE_NAME);
const versionFile = sharedApi.notifierFile(sharedApi.VERSION_FILE_NAME);

/** 种下的那份配置的原文：否定判据用它比对「一个字节都没动过」。 */
function seededConfig(): string {
  return `${JSON.stringify(BASE_SETTINGS, null, 2)}\n`;
}

/** 宿主契约冻结的 8 条浏览器端点（客户端锁定，独立抄写才守得住改路径）。 */
const ROUTE_PATHS: readonly string[] = [
  "/api/dsh-notifier/config",
  "/api/dsh-notifier/history",
  "/api/dsh-notifier/status",
  "/api/dsh-notifier/kinds",
  "/api/dsh-notifier/test",
  "/api/dsh-notifier/health",
  "/api/dsh-notifier/diagnostics",
  "/api/dsh-notifier/events",
];

/**
 * 基础设置：系统出口整个关掉、浏览器出口只弹不响。
 *
 * 系统出口在 Linux 会真的 spawn `notify-send`——测试不该在开发机上弹通知；浏览器出口的帧则
 * 经组合根的 `FrameBus` 进 api 域的流（只写 `seq.json`），是本文件观察「帧走出去了」的唯一手段。
 * 两条内置频道的形态**显式写出来**：`enabled` 是频道唯一的投递闸门，靠 `systemNotify:false`
 * 之类的弹窗键关不掉它（那只让出口无事可做，仍会留下一条 skipped 明细）。
 * `historyMaxAgeDays` 取**非默认值**：逆序释放那条判据要一个与默认值不同的可辨读数。
 */
const BASE_SETTINGS = {
  channels: [
    {
      type: "browser",
      id: "browser",
      enabled: true,
      popup: true,
      sound: false,
      whenVisible: false,
    },
    { type: "system", id: "system", enabled: false, popup: false, sound: false },
  ],
  historyMaxAgeDays: 7,
} as const;

/** 历史行：只取本文件当判据的字段（整体比较会把域内文案变化变成假红）。 */
interface HistoryLine {
  kind?: string;
  message?: string;
  suppressed?: string;
  channels?: ReadonlyArray<{ channelId: string; status: string }>;
}

/** 磁盘上的历史记录。 */
function historyLines(): HistoryLine[] {
  let text: string;
  try {
    text = readFileSync(historyFile, "utf8");
  } catch {
    return [];
  }
  return text
    .split("\n")
    .filter(Boolean)
    .flatMap((line) => {
      try {
        return [JSON.parse(line) as HistoryLine];
      } catch {
        // 坏行不当判据，也不吞掉同行之外的记录
        return [];
      }
    });
}

/** 某一种通知落了几条。 */
function countKind(kind: string): number {
  return historyLines().filter((line) => line.kind === kind).length;
}

/** 磁盘上第一条某一种通知：`beforeEach` 清过历史，所以不受上一个用例干扰。 */
function kindLine(kind: string): HistoryLine | undefined {
  return historyLines().find((line) => line.kind === kind);
}

/** 界碑用的种类名：只出现在界碑行里，任何通知判据都不会撞上它。 */
const SENTINEL_KIND = "itest-sentinel";

/**
 * 排一次界碑并等它落盘，用来给**否定**判据划界。
 *
 * 写队列串行，界碑在磁盘上可见即此前排队的写入全部落盘；没有界碑的「没有新记录」只是抢跑得来的
 * ——它证明的是「还没写完」，不是「不会写」。
 */
async function settleHistory(): Promise<void> {
  storesApi.appendHistory({ ts: Date.now(), kind: SENTINEL_KIND, title: "界碑", message: "-" });
  await pollUntil(() => historyLines().some((line) => line.kind === SENTINEL_KIND), "界碑落盘");
}

/** 浏览器出口的序号：`seq.json` 前进一格 = 帧真的走完了 FrameBus → api 域 → 流。 */
function seqValue(): number {
  try {
    const parsed = Number.parseInt(readFileSync(seqFile, "utf8").trim(), 10);
    return Number.isFinite(parsed) ? parsed : 0;
  } catch {
    return 0;
  }
}

/**
 * 本用例的序号锚点（每轮 +1000）。
 *
 * 序号是 fire-and-forget 写，「等于锚点 +1」这类判据要挡得住上一个用例迟到的那一笔——递增的锚点
 * 让迟到的值必然小于本轮的起点，于是「文件里出现了本轮的格子」只可能由本轮自己的广播产生。
 */
let seqAnchor = 0;

function seedSeqAnchor(): void {
  seqAnchor += 1000;
  mkdirSync(dirname(seqFile), { recursive: true });
  writeFileSync(seqFile, `${seqAnchor}\n`);
}

/** 写一份设置文件（组合根装配时同步读它，故必须用同步写）。 */
function seed(settings: Record<string, unknown>): void {
  mkdirSync(dirname(configFile), { recursive: true });
  writeFileSync(configFile, `${JSON.stringify(settings, null, 2)}\n`);
}

/** 假会话日志条目：本块只读 `type` 与 `data`（与 events 域单测同一口径）。 */
function turnEndEvent(turn: number, kind: string): SessionEvent {
  return { type: "turn/end", data: { turn, reason: { kind } } } as unknown as SessionEvent;
}

/** 假 agent：只露出 events 域真的会读的几处（`id` 与 `session` 的 header / 日志快照）。 */
function fakeAgent(
  id: string,
  events: SessionEvent[] = [],
  header: Record<string, unknown> = {},
): Agent {
  return {
    id,
    session: { header, snapshotEvents: () => events },
  } as unknown as Agent;
}

/** 假会话：`session/event` 的载荷带整份会话对象，而本插件只用它的 `id`。 */
function fakeSession(id: string): Session {
  return { id } as unknown as Session;
}

/**
 * 宿主按作用域派发时传的 `this`：`agent/*` 声明的是 `Scoped<Agent>`、`session/event` 是
 * `Scoped<Session>`，而那个 brand 不是本包的依赖，故从事件签名上取 `this` 位。测试要造的正是
 * `{ [Context.filter]: … }` 这一个成员——直接抄 `Scoped<…>` 会把它变成第二份事实源。
 */
type ScopedThis<K extends keyof Events> = EventThis<Events[K]>;

/** 作用域收紧的派发载体：filter 恒假，于是**只有** `{ global: true }` 的订阅能收到。 */
function scopeRejecting<K extends keyof Events>(): ScopedThis<K> {
  return { [Context.filter]: () => false } as unknown as ScopedThis<K>;
}

/**
 * 假 settings 服务只提供 describe 低优先级兜底；正式历史来源由 upgrade 域直接读取 DSH_HOME 双文件。
 * `describe()` 在真实宿主里只列**已注册**的命名空间，所以这里的 `user` 用三种取值对应三种真实形态：
 * `undefined` = 没注册这条命名空间（新架构的常态，服务面读不到）；`{}` = 注册了但 user 层为空；有键 = 注册且用户设过。
 */
function fakeSettings(user: Record<string, unknown> | undefined): { describe: () => unknown[] } {
  return {
    describe: () => (user === undefined ? [] : [{ ns: "dsh-notifier", user }]),
  };
}

/**
 * 假宿主 webServer：只实现组合根够得着的那一面（`register`），并记下摘除时的现场。
 *
 * `failAt` 让第 N 条摘除器抛错——宿主摘路由失败是真实会发生的（路由已被别人摘掉、宿主换实现），
 * 组合根的释放壳对它的承诺是「不阻断其余」。
 */
function fakeWebServer(
  observe: () => { configDays: number; serviceAlive: boolean },
  options: { failAt?: number } = {},
) {
  const routes: WebRoute[] = [];
  const removals: Array<{ path: string; configDays: number; serviceAlive: boolean }> = [];
  const service = {
    register(route: WebRoute) {
      routes.push(route);
      return () => {
        removals.push({ path: route.path, ...observe() });
        if (removals.length === options.failAt) throw new Error(`摘除失败：${route.path}`);
      };
    },
  } as unknown as Context["webServer"];
  return { service, routes, removals };
}

/** 假宿主 agent 注册表：只实现组合根读的两处（`get` 与 `isOwnedBy`）。 */
function fakeAgents(parent: Agent, child: Agent): Context["agents"] {
  return {
    get: (id: string) => (id === parent.id ? parent : undefined),
    isOwnedBy: (id: string, owner: Agent) => id === child.id && owner === parent,
  } as unknown as Context["agents"];
}

/**
 * 日志出口：`LoggerService` 的公开扩展点，用它把 warn 收进数组。
 *
 * 为什么不读内置的 `ctx.logger.buffer`：那个出口的阈值是 INFO，warn（级别 2）落在它之外，
 * buffer 里永远看不到本文件的判据文案。阈值按 `levels.default` 给——它是出口自己的约定。
 */
function captureWarnings(root: Context): string[] {
  const warnings: string[] = [];
  root.logger.exporter({
    levels: { default: 2 },
    export: (message) => {
      if (message.type === "warn") warnings.push(String(message.args[0]));
    },
  });
  return warnings;
}

/** 一次挂载的全部观测物。 */
interface Mounted {
  readonly root: Context;
  readonly fiber: Fiber;
  readonly host: ReturnType<typeof fakeWebServer>;
  /** 宿主日志出口收到的 warn 文案（组合根只经它报错）。 */
  readonly warns: string[];
  unmount(): Promise<void>;
}

/** 已挂载但用例没显式卸载的实例：`afterEach` 兜底收掉，免得路由/心跳漏到下一个用例。 */
let live: Fiber | null = null;

/**
 * 按宿主的真实挂载顺序装配：先 provide 宿主服务，再 `ctx.plugin(插件)`。
 *
 * `settings` 是本插件的**显式依赖**（组合根的 `inject`）：宿主保证它在插件装配前就绪，所以这里
 * 总是先 provide 一个假的；`settings` 的值就是那份 0.2.3 存量命名空间的 user 层（缺省 = 有服务
 * 但没存量）。「服务没来」这条分支已不属于本插件——它变成 cordis 的 inject 门（见 inject 门用例）。
 * `services` 是其余宿主服务（如 `agents`）——装与不装是两条不同的判定路径。
 */
async function mount(options: {
  config?: { enabled?: boolean };
  settings?: Record<string, unknown>;
  services?: Record<string, unknown>;
}): Promise<Mounted> {
  const root = new Context();
  root.provide("settings", fakeSettings(options.settings));
  for (const [name, value] of Object.entries(options.services ?? {})) root.provide(name, value);
  const warns = captureWarnings(root);
  const host = fakeWebServer(() => ({
    configDays: configApi.readConfig().historyMaxAgeDays,
    serviceAlive: root.get("wingsky.notifier", false) !== undefined,
  }));
  root.provide("webServer", host.service);
  const fiber = await root.plugin(notifier, options.config);
  live = fiber;
  return {
    root,
    fiber,
    host,
    warns,
    unmount: async () => {
      live = null;
      await fiber.dispose();
    },
  };
}

/**
 * 模拟宿主内置 answerer：链上**更早注册**的那一个，它给出的判定就是这次请求的最终结果。
 * 它不调 `next()`——宿主自己的应答者拿到判定后即短路，这正是本插件必须 prepend 的理由。
 */
async function mountApprovalAnswerer(
  root: Context,
  calls: string[],
  outcome: ApprovalOutcome,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("approval/request", () => {
      calls.push("answerer");
      return Promise.resolve(outcome);
    });
  });
}

/** 同上，提问那条链上的 answerer（两条 waterfall 同构，夹具分开写以免一条覆盖另一条）。 */
async function mountQuestionAnswerer(
  root: Context,
  calls: string[],
  answer: AskUserQuestionAnswer,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("user-questions/request", () => {
      calls.push("answerer");
      return Promise.resolve(answer);
    });
  });
}

