/**
 * dsh-notifier pipeline 域 dispatch 块 —— 重试、退避、节流、在途门与逐频道归位。
 *
 * 判据为什么是这些：
 *  - 重试次数与退避时刻是**出口不可见**的承诺：出口只说「可不可重试」，把 4xx 重投三次或把
 *    网络失败丢掉，用户看到的都是「通知有时来有时不来」；
 *  - system 出口的 1 秒节流挡的是连点测试按钮刷屏；跳过的那一次**没有投递**，归档必须如实说这一条，
 *    把上一次的结论透传给本次会让两行都变成无可追溯的，而通知记录是用户唯一能逐条看的投递面；
 *  - 在途门与逐频道归位决定「慢出口会不会被并发踩」以及「失败记到谁头上」。
 *
 * 时间纪律：重试用例用假时钟推进（真等是 3 秒/例），节流用例只用 `vi.setSystemTime` 钉住
 * 「现在」——它单独用只换掉 `globalThis.Date`，不碰事件循环。时钟被钉住时不能用 `pollUntil`
 * （它的截止时间读 `Date.now()`，谓词不成立就永不超时），故那两处用 `settleMicrotasks`。
 * 「首投递未完成」那条同样钉住「现在」（两条提交必须落在同一节流窗内），等终态一律用
 * `settleMicrotasks`——判据不能落在「两次调用之间真实耗时小于 1 秒」上：CI 与 Stryker 并发
 * 下的停顿会把确定性判据变成偶发假红。
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import type { NotifyConfig } from "../../../src/server/config/impl/model/type.ts";
import type { DeliverReason } from "../../../src/server/shared/interface.ts";
import type {
  ChannelsPort,
  HistoryEntry,
  NotifyMessage,
  OutgoingFrame,
  PipelineDeps,
} from "../../../src/server/pipeline/deps.ts";
import {
  installPipeline,
  releasePipeline,
  submit,
} from "../../../src/server/pipeline/interface.ts";
import type { NotifyRequest } from "../../../src/server/pipeline/interface.ts";
import { makeLogger, pollUntil, settleMicrotasks } from "../../helpers.ts";

/** 出站频道配置：经设置模型可达，不必请别的块再导出一个名字。 */
type ChannelConfig = NotifyConfig["channels"][number];
type BarkConfig = Extract<ChannelConfig, { type: "bark" }>;
type WebhookConfig = Extract<ChannelConfig, { type: "webhook" }>;

/** 投递目标的形状经端口签名可达。 */
type DeliveryTarget = Parameters<ChannelsPort["deliver"]>[1][number];

/** 默认表里的内置频道：泛型只为把「按 type 找到的那条」收窄成对应型号——查找条件就是 type 相等。 */
function builtinOf<T extends "browser" | "system">(type: T): Extract<ChannelConfig, { type: T }> {
  const found = DEFAULT_CONFIG.channels.find((channel) => channel.type === type);
  if (found === undefined) throw new Error(`默认表里缺内置频道 ${type}`);
  return found as Extract<ChannelConfig, { type: T }>;
}

/**
 * 关掉两条内置出口：本块要数的是出站频道的投递次数与节奏。
 *
 * 停用只能写在 `channels` 的条目上：`browserNotify` 一类顶层键现在是读面派生出来的只读投影，
 * 改它们不会让内置出口少投一次，计数用例会凭空多出两次投递。
 */
function builtinsOff(): ChannelConfig[] {
  return [
    { ...builtinOf("browser"), enabled: false },
    { ...builtinOf("system"), enabled: false },
  ];
}

/** 装配面夹具：只伪 `pipeline/deps.ts` 声明的那几个端口，顺手记下四件观测物。 */
interface Harness {
  readonly history: HistoryEntry[];
  readonly statuses: Array<{
    channelId: string;
    status: "ok" | "failed";
    error: DeliverReason | undefined;
  }>;
  readonly logger: ReturnType<typeof makeLogger>;
  readonly useConfig: (patch?: Partial<NotifyConfig>) => void;
  readonly onDeliver: (deliver: ChannelsPort["deliver"]) => void;
  /** 让某个频道的状态写面违约（状态文件不可写）：观测面自己坏掉时的行为另算一档。 */
  readonly breakStatusWrites: (channelId: string) => void;
}

function requestOf(over: Partial<NotifyRequest> = {}): NotifyRequest {
  return { kind: "done", title: "标题", body: "正文", ...over };
}

function barkChannel(over: Partial<BarkConfig> = {}): BarkConfig {
  return {
    type: "bark",
    id: "a",
    enabled: true,
    baseUrl: "http://127.0.0.1:40281/bark",
    deviceKey: "dk",
    ...over,
  };
}

function webhookChannel(over: Partial<WebhookConfig> = {}): WebhookConfig {
  return {
    type: "webhook",
    id: "w",
    enabled: true,
    url: "http://127.0.0.1:40281/hook",
    auth: "none",
    ...over,
  };
}

/** 只留 system 出口的设置：节流用例要「唯一目标」才数得清投递次数。 */
function systemOnly(): Partial<NotifyConfig> {
  return {
    channels: [
      { ...builtinOf("browser"), enabled: false },
      { ...builtinOf("system"), enabled: true, popup: true, sound: false },
    ],
  };
}

function assemble(): Harness {
  const history: HistoryEntry[] = [];
  const statuses: Harness["statuses"][number][] = [];
  const frames: OutgoingFrame[] = [];
  const logger = makeLogger();
  const brokenStatus = new Set<string>();
  const state: { config: NotifyConfig; deliver: ChannelsPort["deliver"] } = {
    config: DEFAULT_CONFIG,
    deliver: async (_message: NotifyMessage, targets: DeliveryTarget[]) =>
      targets.map(() => ({ status: "ok", stage: "delivered" })),
  };
  const deps: PipelineDeps = {
    enabled: true,
    frames: {
      emit: (payload) => {
        frames.push(payload);
      },
    },
    logger,
    config: { readConfig: () => state.config },
    stores: {
      appendHistory: (entry) => {
        history.push(entry);
      },
      recordStatus: (channelId, status, error) => {
        if (brokenStatus.has(channelId)) throw new Error("状态写面违约");
        statuses.push({ channelId, status, error });
      },
    },
    channels: { deliver: (message, targets) => state.deliver(message, targets) },
  };
  installPipeline(deps);
  return {
    history,
    statuses,
    logger,
    useConfig: (patch = {}) => {
      state.config = { ...DEFAULT_CONFIG, ...patch };
    },
    onDeliver: (deliver) => {
      state.deliver = deliver;
    },
    breakStatusWrites: (channelId) => {
      brokenStatus.add(channelId);
    },
  };
}

afterEach(() => {
  releasePipeline();
  vi.useRealTimers();
});

describe("重试与退避（假时钟推进，不真等 3 秒）", () => {
  beforeEach(() => {
    vi.useFakeTimers({ toFake: ["setTimeout", "clearTimeout", "Date"] });
    vi.setSystemTime(new Date(2026, 0, 15, 12, 0, 0));
  });

  // 退避时刻写错（例如固定 0ms）会把可重试失败变成对上游的连打。
  it("bark 重试 2 次、退避 1000/2000ms：次数与时刻都由管线说了算", async () => {
    const harness = assemble();
    harness.useConfig({ channels: [...builtinsOff(), barkChannel()] });
    let attempts = 0;
    harness.onDeliver(async (_message, targets) => {
      attempts += targets.length;
      return targets.map(() => ({
        status: "failed",
        stage: "delivered",
        reason: { code: "reasonBarkHttp", params: { status: 503 } },
        retryable: true,
      }));
    });

    submit(requestOf());
    expect(attempts).toBe(1);
    await vi.advanceTimersByTimeAsync(0);
    await vi.advanceTimersByTimeAsync(999);
    expect(attempts).toBe(1);
    await vi.advanceTimersByTimeAsync(1);
    expect(attempts).toBe(2);
    await vi.advanceTimersByTimeAsync(1999);
    expect(attempts).toBe(2);
    await vi.advanceTimersByTimeAsync(1);
    expect(attempts).toBe(3);
    // 上限之外不再重投：maxRetries=2 是硬上限，不是「至少两次」。
    await vi.advanceTimersByTimeAsync(60_000);
    expect(attempts).toBe(3);
  });

  // 重试的停止条件有两个：不可重试与已成功。只测「一直失败」的话，重投循环丢掉「重新取结果」
  // 也全绿——而那样第二条已送达的通知会被再投两遍，并在归档里被记成失败。
  it("重试中途成功即停止：第二次成功不再重投，也不写失败", async () => {
    const harness = assemble();
    harness.useConfig({ channels: [...builtinsOff(), barkChannel()] });
    let attempts = 0;
    harness.onDeliver(async (_message, targets) => {
      attempts += targets.length;
      return attempts === 1
        ? [
            {
              status: "failed" as const,
              stage: "delivered" as const,
              reason: { code: "reasonBarkHttp", params: { status: 503 } },
              retryable: true,
            },
          ]
        : [{ status: "ok" as const, stage: "delivered" as const }];
    });

    submit(requestOf());
    await vi.advanceTimersByTimeAsync(1000);
    expect(attempts).toBe(2);

    // 第二次已经成功：上限之内也不许再投，否则同一条通知会在对端出现两遍。
    await vi.advanceTimersByTimeAsync(60_000);
    expect(attempts).toBe(2);

    await settleMicrotasks();
    expect(harness.history[0]!.channels).toEqual([{ channelId: "bark:a", status: "ok" }]);
    expect(harness.statuses).toEqual([{ channelId: "bark:a", status: "ok", error: undefined }]);
  });

  // 出口说不可重试却重投，等于让对端把同一条通知处理多遍。
  it("出口标 retryable=false 时一次也不多投：分类是出口的责任，管线照办", async () => {
    const harness = assemble();
    harness.useConfig({ channels: [...builtinsOff(), barkChannel()] });
    let attempts = 0;
    harness.onDeliver(async (_message, targets) => {
      attempts += targets.length;
      return targets.map(() => ({
        status: "failed",
        stage: "delivered",
        reason: { code: "reasonBarkRejected", params: { code: "400" }, detail: "设备未注册" },
        retryable: false,
      }));
    });

    submit(requestOf());
    await vi.advanceTimersByTimeAsync(10_000);
    expect(attempts).toBe(1);
  });

  // webhook 不幂等，策略表漏了 maxRetries=0 就会重投。
  it("webhook 零重试：即便出口标了 retryable 也不重投（策略表 maxRetries=0）", async () => {
    const harness = assemble();
    harness.useConfig({ channels: [...builtinsOff(), webhookChannel()] });
    let attempts = 0;
    harness.onDeliver(async (_message, targets) => {
      attempts += targets.length;
      return targets.map(() => ({
        status: "failed",
        stage: "delivered",
        reason: { code: "reasonWebhookHttp", params: { status: 502 } },
        retryable: true,
      }));
    });

    submit(requestOf());
    await vi.advanceTimersByTimeAsync(10_000);
    expect(attempts).toBe(1);
  });
});

describe("逐频道归位", () => {
  // 失败记到别的频道头上，用户会去查一个根本没问题的频道。
  it("终态写频道状态并按频道归位进历史明细：失败原因只在失败那一支上", async () => {
    const harness = assemble();
    harness.useConfig({
      channels: [...builtinsOff(), barkChannel({ id: "a" }), webhookChannel({ id: "w" })],
    });
    harness.onDeliver(async (_message, targets) =>
      targets.map((target) =>
        target.type === "webhook"
          ? {
              status: "failed" as const,
              stage: "delivered" as const,
              reason: { code: "reasonWebhookHttp", params: { status: 401 } },
              retryable: false,
            }
          : { status: "ok" as const, stage: "delivered" as const },
      ),
    );

    submit(requestOf());
    await pollUntil(() => harness.history.length === 1, "发出归档落史");

    // 频道状态按**完成顺序**落（两个出口并发），故只按频道身份查证结论；顺序判据在归档明细上。
    const statusOf = (channelId: string) =>
      harness.statuses.find((entry) => entry.channelId === channelId);
    expect(harness.statuses).toHaveLength(2);
    expect(statusOf("bark:a")?.status).toBe("ok");
    expect(statusOf("bark:a")?.error).toBeUndefined();
    expect(statusOf("webhook:w")?.status).toBe("failed");
    expect(statusOf("webhook:w")?.error).toEqual({
      code: "reasonWebhookHttp",
      params: { status: 401 },
    });
    expect(harness.history[0]!.channels).toEqual([
      { channelId: "bark:a", status: "ok" },
      {
        channelId: "webhook:w",
        status: "failed",
        reason: { code: "reasonWebhookHttp", params: { status: 401 } },
      },
    ]);
  });

  // 一次违约让整批一起拒绝，健康频道的明细与状态跟着消失——故障时最需要的那条证据正好没有。
  it("出口违约不牵连同批：违约频道出一条 failed 明细，健康频道照常投递并写状态，整批不拒绝", async () => {
    const harness = assemble();
    harness.useConfig({
      channels: [
        ...builtinsOff(),
        barkChannel({ id: "a", deviceKey: "dk-a" }),
        barkChannel({ id: "b", deviceKey: "dk-b" }),
      ],
    });
    harness.onDeliver(async (_message, targets) => {
      const target = targets[0]!;
      if (target.type === "bark" && target.deviceKey === "dk-a") {
        throw new Error("出口实现违约");
      }
      return targets.map(() => ({ status: "ok", stage: "delivered" }));
    });

    submit(requestOf());
    await settleMicrotasks();

    // 明细与 `targets` 同序：违约落在它自己的频道上，健康频道照常留痕。
    expect(harness.history[0]!.channels).toEqual([
      {
        channelId: "bark:a",
        status: "failed",
        reason: { code: "reasonChannelThrew", detail: "出口实现违约" },
      },
      { channelId: "bark:b", status: "ok" },
    ]);
    // 频道状态按完成顺序落（两个出口并发），故只按频道身份查证结论。
    const statusOf = (channelId: string) =>
      harness.statuses.find((entry) => entry.channelId === channelId);
    expect(statusOf("bark:a")?.status).toBe("failed");
    expect(statusOf("bark:a")?.error).toEqual({
      code: "reasonChannelThrew",
      detail: "出口实现违约",
    });
    expect(statusOf("bark:b")?.status).toBe("ok");
    // 整批没有拒绝：调用方那条「投递失败」的兜底 warn 不该被触发（它一响，说明明细已经丢了）。
    expect(harness.logger.warns).toEqual([]);
  });

  // 状态只是观测面：它自己违约若升级成抛出，明细已经拿到手也会被整批带走，等于观测面反过来吃掉事实。
  it("违约频道的状态写面再次违约也不抛出：failed 明细照常进归档，原因仍是出口那条", async () => {
    const harness = assemble();
    harness.useConfig({
      channels: [
        ...builtinsOff(),
        barkChannel({ id: "a", deviceKey: "dk-a" }),
        barkChannel({ id: "b", deviceKey: "dk-b" }),
      ],
    });
    harness.breakStatusWrites("bark:a");
    harness.onDeliver(async (_message, targets) => {
      const target = targets[0]!;
      if (target.type === "bark" && target.deviceKey === "dk-a") {
        throw new Error("出口实现违约");
      }
      return targets.map(() => ({ status: "ok", stage: "delivered" }));
    });

    submit(requestOf());
    await settleMicrotasks();

    // 状态写不进去只少一条观测记录，不被状态层的错盖掉、也不改变本次投递的结论。
    expect(harness.history[0]!.channels).toEqual([
      {
        channelId: "bark:a",
        status: "failed",
        reason: { code: "reasonChannelThrew", detail: "出口实现违约" },
      },
      { channelId: "bark:b", status: "ok" },
    ]);
    expect(harness.statuses.map((entry) => `${entry.channelId}:${entry.status}`)).toEqual([
      "bark:b:ok",
    ]);
    expect(harness.logger.warns).toEqual([]);
  });

  // 出口按配置判定「这次没有可发的内容」时，结果既不是成功也不是失败：状态面不该因此多出一条
  // 「最后一次投递结论」（写 ok 等于替出口宣称投递成功），而历史必须如实留下这次跳过。
  it("出口报 skipped：历史如实记一条跳过与原因，频道状态不被写（没有结论可言）", async () => {
    const harness = assemble();
    const reason = { code: "reasonSkipConfig" } as const;
    harness.onDeliver(async (_message, targets) =>
      targets.map(() => ({ status: "skipped" as const, reason })),
    );

    submit(requestOf());
    await pollUntil(() => harness.history.length === 1, "skipped 落史");
    expect(harness.history[0]!.channels).toEqual([
      { channelId: "browser", status: "skipped", reason },
      { channelId: "system", status: "skipped", reason },
    ]);
    expect(harness.statuses).toEqual([]);
  });
});

describe("节奏：节流与在途门", () => {
  // 跳过时凭空造一条失败，用户会在状态页看到不存在的故障；照抄上一次的结论，则是替一次没发生的
  // 投递背书。两者都不行：唯一诚实的那条记录是「本次没投递，因为节流」。
  it("system 出口 1 秒节流：窗口内不投递并如实记一条 skipped（不照抄上一次的结论）", async () => {
    const harness = assemble();
    harness.useConfig(systemOnly());
    let attempts = 0;
    harness.onDeliver(async (_message, targets) => {
      attempts += targets.length;
      return targets.map(() => ({ status: "ok", stage: "delivered" }));
    });

    vi.setSystemTime(new Date(2026, 0, 15, 12, 0, 0));
    submit(requestOf());
    await settleMicrotasks();
    expect(attempts).toBe(1);

    submit(requestOf());
    await settleMicrotasks();
    expect(attempts).toBe(1);
    expect(harness.history[1]!.channels).toEqual([
      { channelId: "system", status: "skipped", reason: { code: "reasonThrottled" } },
    ]);
    // 上一次那一条不能被改写：它的结论属于它自己那一次投递。
    expect(harness.history[0]!.channels).toEqual([{ channelId: "system", status: "ok" }]);

    vi.setSystemTime(new Date(2026, 0, 15, 12, 0, 1));
    submit(requestOf());
    await settleMicrotasks();
    expect(attempts).toBe(2);
  });

  // 首投递还在途时没有任何失败证据：跳过若把「还没结论」写成失败，用户连点测试按钮就会在状态页
  // 看到一条不存在的故障。该路径要求第一次投递仍挂在未决 promise 上，故钉住「现在」让两条提交
  // 落在同一节流窗内，等待一律走微任务排水。
  it("首投递尚未完成时的节流跳过：不产生第二次投递，也不替首条预支结论", async () => {
    const harness = assemble();
    harness.useConfig(systemOnly());
    const inFlight: Array<() => void> = [];
    let attempts = 0;
    harness.onDeliver(async (_message, targets) => {
      attempts += targets.length;
      await new Promise<void>((resolve) => {
        inFlight.push(resolve);
      });
      return targets.map(() => ({
        status: "failed" as const,
        stage: "delivered" as const,
        reason: { code: "reasonSystemPopupFailed", params: { bin: "notify-send" } },
        retryable: false,
      }));
    });

    vi.setSystemTime(new Date(2026, 0, 15, 12, 0, 0));
    submit(requestOf({ title: "第一条" }));
    await settleMicrotasks();
    expect(attempts).toBe(1);
    expect(inFlight).toHaveLength(1);

    // 时钟没有前进：这条提交必然落在首条开启的 1 秒节流窗内，而首条仍未拿到结论。
    submit(requestOf({ title: "第二条" }));
    await settleMicrotasks();

    // 跳过就是跳过：首条此刻还没有结论，这一条既不能宣称成功（假定成功）也不能宣称失败。
    expect(attempts).toBe(1);
    expect(harness.history[0]!.title).toBe("第二条");
    expect(harness.history[0]!.channels).toEqual([
      { channelId: "system", status: "skipped", reason: { code: "reasonThrottled" } },
    ]);
    // 没有投递就没有结论可写：跳过不该在频道状态里补一条。
    expect(harness.statuses).toEqual([]);

    inFlight.shift()?.();
    await settleMicrotasks();
    expect(harness.history).toHaveLength(2);
    expect(harness.history[1]!.title).toBe("第一条");
    expect(harness.history[1]!.channels).toEqual([
      {
        channelId: "system",
        status: "failed",
        reason: { code: "reasonSystemPopupFailed", params: { bin: "notify-send" } },
      },
    ]);
  });

  // 出口违约时槽位同样要放开：漏一次，该频道的在途计数就永久 +1，两次之后它的通知全部卡在队列里，
  // 表现为「这个频道从此再也不发通知」，而通道本身没有任何错误。
  it("出口违约会放开它在途槽位：两次违约之后第三条照常开投（漏释放即该频道永久卡死）", async () => {
    const harness = assemble();
    harness.useConfig({ channels: [...builtinsOff(), barkChannel()] });
    let calls = 0;
    harness.onDeliver(async (_message, targets) => {
      calls += targets.length;
      if (calls <= 2) throw new Error("出口实现违约");
      return targets.map(() => ({ status: "ok", stage: "delivered" }));
    });

    submit(requestOf());
    submit(requestOf());
    await pollUntil(() => harness.history.length === 2, "两条违约各自归档");
    expect(harness.logger.warns).toEqual([]);

    submit(requestOf());
    await pollUntil(() => harness.history.length === 3, "槽位释放后第三条开投");
    expect(harness.history[2]!.channels).toEqual([{ channelId: "bark:a", status: "ok" }]);
  });

  // 无上限并发会把同一频道打爆；门形同虚设则慢出口会被并发踩。
  it("在途门：同频道并发上限 2，第 3 条排队到有槽位才开投（慢出口不该被无限并发踩）", async () => {
    const harness = assemble();
    harness.useConfig({ channels: [...builtinsOff(), barkChannel()] });
    const pending: Array<() => void> = [];
    let started = 0;
    harness.onDeliver(async (_message, targets) => {
      started += targets.length;
      await new Promise<void>((resolve) => {
        pending.push(resolve);
      });
      return targets.map(() => ({ status: "ok", stage: "delivered" }));
    });

    submit(requestOf());
    submit(requestOf());
    submit(requestOf());
    await pollUntil(() => started === 2, "前两条应立刻开投");
    expect(pending).toHaveLength(2);

    pending.shift()?.();
    await pollUntil(() => started === 3, "槽位释放后队首才开投");
    for (const release of pending.splice(0)) release();
    await pollUntil(() => harness.history.length === 3, "三条都要归档");
  });
});

/**
 * dsh-notifier pipeline 域 route 块 —— 这条通知该发给谁（纯函数，判据全来自设置）。
 *
 * 判据为什么是这些：
 *  - `kindRoutes` 命中与缺省广播是「用户改了路由却不生效」的唯一解释面；
 *  - `stale` 只对配置里**根本不存在**的 id 报，停用不算已删除——旧实现按「不在投递池里」判，
 *    用户一停用频道就收到一串「指向已删除频道」的误导告警；
 *  - 投递池对每个频道只有 `enabled` 一个判据：弹窗与声音都关的频道照样进池，由出口回答
 *    「这一次没有可发的内容」——在管线里按弹窗 / 声音剔目标，等于替出口决定它该发什么，
 *    而出口的回答还会被伪装成一次投递成功（全关即出池时，用户连 skipped 都看不到）；
 *  - 目标构造里的取舍（空串=没配置、badge 0 有语义、`levels[kind]` 优先于 `level`）决定出口
 *    实际收到什么，写错一处就是「设置页上明明填了，通知里却没有」。
 * 路由是纯函数，故这里只喂设置与假帧出口，不经装配面。
 */
import { describe, expect, it } from "vitest";

import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import type { NotifyConfig } from "../../../src/server/config/impl/model/type.ts";
import { routeTargets } from "../../../src/server/pipeline/impl/route/index.ts";
// 频道 id 规则的事实源是 src/shared/channels.ts（两端共享面）——客户端消费同一份函数，
// 故这条判据测的就是两端共用的那一份实现。
import { channelIdOf } from "../../../src/shared/interface.ts";
import type {
  BarkConfig,
  BarkTarget,
  BrowserConfig,
  ChannelConfig,
  RouteOutcome,
  SystemConfig,
  WebhookConfig,
  WebhookTarget,
} from "../../../src/server/pipeline/impl/route/type.ts";
import type {
  DeliveryTarget,
  FramePort,
  OutgoingFrame,
} from "../../../src/server/pipeline/deps.ts";
import type { NotifyFrame } from "../../../src/server/channels/interface.ts";
import type { NotifyRequest } from "../../../src/server/pipeline/interface.ts";
import { makeLogger } from "../../helpers.ts";

/** 浏览器官口的投递参数：经投递目标联合可达，不必请 channels 域再导出一个名字。 */
type BrowserTarget = Extract<DeliveryTarget, { type: "browser" }>;

function configAt(over: Partial<NotifyConfig> = {}): NotifyConfig {
  return { ...DEFAULT_CONFIG, ...over };
}

/**
 * 内置两频道：默认表就带它们且恒在最前，故这里取默认表的真实值再覆盖字段——用例写死的
 * 默认值一旦与默认表漂移，读面物化的形态就没人替它把关了。
 */
function builtins(
  over: { browser?: Partial<BrowserConfig>; system?: Partial<SystemConfig> } = {},
): ChannelConfig[] {
  const browser = DEFAULT_CONFIG.channels.find(
    (channel): channel is BrowserConfig => channel.type === "browser",
  );
  const system = DEFAULT_CONFIG.channels.find(
    (channel): channel is SystemConfig => channel.type === "system",
  );
  if (browser === undefined || system === undefined) throw new Error("默认表里缺内置频道");
  return [
    { ...browser, ...over.browser },
    { ...system, ...over.system },
  ];
}

function requestOf(over: Partial<NotifyRequest> = {}): NotifyRequest {
  return { kind: "done", title: "标题", body: "正文", ...over };
}

function barkChannel(over: Partial<BarkConfig> = {}): BarkConfig {
  return {
    type: "bark",
    id: "a",
    enabled: true,
    baseUrl: "http://127.0.0.1:40281/bark",
    deviceKey: "dk",
    ...over,
  };
}

function webhookChannel(over: Partial<WebhookConfig> = {}): WebhookConfig {
  return {
    type: "webhook",
    id: "w",
    enabled: true,
    url: "http://127.0.0.1:40281/hook",
    auth: "none",
    ...over,
  };
}

/** 帧出口的假实现：帧是浏览器目标的唯一产物，收帧即观测到路由接线。 */
function framePort(): { port: FramePort; emitted: OutgoingFrame[] } {
  const emitted: OutgoingFrame[] = [];
  return {
    port: {
      emit: (payload) => {
        emitted.push(payload);
      },
    },
    emitted,
  };
}

/** 取指定频道的投递参数；没有就判红——断言的前置条件不该在后面变成一串 undefined 比较。 */
function targetOf(outcome: RouteOutcome, channelId: string): DeliveryTarget {
  const found = outcome.targets.find((routed) => routed.channelId === channelId);
  if (found === undefined) throw new Error(`路由结果里没有 ${channelId}`);
  return found.target;
}

function barkTargetOf(outcome: RouteOutcome, channelId: string): BarkTarget {
  const target = targetOf(outcome, channelId);
  if (target.type !== "bark") throw new Error(`${channelId} 不是 bark 目标`);
  return target;
}

function webhookTargetOf(outcome: RouteOutcome, channelId: string): WebhookTarget {
  const target = targetOf(outcome, channelId);
  if (target.type !== "webhook") throw new Error(`${channelId} 不是 webhook 目标`);
  return target;
}

function browserTargetOf(outcome: RouteOutcome, channelId: string): BrowserTarget {
  const target = targetOf(outcome, channelId);
  if (target.type !== "browser") throw new Error(`${channelId} 不是浏览器目标`);
  return target;
}

/** 系统出口的投递参数：`popup` 的取值只有在这里看得见。 */
function systemTargetOf(
  outcome: RouteOutcome,
  channelId: string,
): Extract<DeliveryTarget, { type: "system" }> {
  const target = targetOf(outcome, channelId);
  if (target.type !== "system") throw new Error(`${channelId} 不是系统目标`);
  return target;
}

describe("kindRoutes：命中收窄，缺省广播", () => {
  // 路由命中不生效，用户看到的是「设置改了没用」。
  it("命中时只投命中的频道实例（改了路由就要生效）", () => {
    const outcome = routeTargets(
      { frames: framePort().port, logger: makeLogger() },
      configAt({
        channels: [...builtins(), barkChannel({ id: "a" }), barkChannel({ id: "b" })],
        kindRoutes: { done: ["bark:b"] },
      }),
      requestOf(),
    );
    expect(outcome.targets.map((routed) => routed.channelId)).toEqual(["bark:b"]);
    expect(outcome.stale).toEqual([]);
  });

  // 缺省广播是绝大多数用户的形态，漏掉停用判断会把通知发到用户已经关掉的频道。
  it("缺省与空数组都是广播全部启用频道，停用的不进池；顺序为内置在前、出站随后", () => {
    const channels: ChannelConfig[] = [
      ...builtins(),
      barkChannel({ id: "a" }),
      barkChannel({ id: "off", enabled: false }),
      webhookChannel({ id: "w" }),
    ];
    const broadcastCases: Array<Record<string, string[]>> = [{}, { done: [] }];
    for (const kindRoutes of broadcastCases) {
      const outcome = routeTargets(
        { frames: framePort().port, logger: makeLogger() },
        configAt({ channels, kindRoutes }),
        requestOf(),
      );
      expect(
        outcome.targets.map((routed) => routed.channelId),
        JSON.stringify(kindRoutes),
      ).toEqual(["browser", "system", "bark:a", "webhook:w"]);
    }
  });

  // 这条规则是跨端契约：客户端与本块消费同一份 `channelIdOf`（src/shared/channels.ts），
  // 算出来的 id 因此逐字一致——否则 chips 写进 kindRoutes 的 id 与池里的 id 对不上，用户勾了却收不到。
  it("频道对外 id：内置取 type（裸 id），实例取 type:id", () => {
    expect(channelIdOf(builtins()[0]!)).toBe("browser");
    expect(channelIdOf(builtins()[1]!)).toBe("system");
    expect(channelIdOf(barkChannel({ id: "phone" }))).toBe("bark:phone");
  });

  // 反过来锁 `knownChannelIds`：内置条目必须按裸 id 计入、不能再按 `type:id` 加一遍——多出来的
  // `browser:browser` 会把一条自造 id 认成「已知频道」，用户写成它时收不到「指向已删除频道」的提醒。
  it("kindRoutes：内置裸 id 命中且不报 stale，自造的 type:id 仍被认成不存在", () => {
    const deps = { frames: framePort().port, logger: makeLogger() };
    const staleOf = (ids: string[]) =>
      routeTargets(deps, configAt({ kindRoutes: { done: ids } }), requestOf()).stale;
    expect(staleOf(["browser", "system"])).toEqual([]);
    expect(staleOf(["browser:browser"])).toEqual(["browser:browser"]);
  });

  // onlyChannel 是单频道测试按钮的唯一入口，被 kindRoutes 拦下就等于测试按钮失灵。
  it("onlyChannel 直接收窄到一处并绕过 kindRoutes；查不到就是空结果，不报 stale", () => {
    const deps = { frames: framePort().port, logger: makeLogger() };
    const config = configAt({
      channels: [...builtins(), barkChannel({ id: "a" }), barkChannel({ id: "b" })],
      kindRoutes: { done: ["bark:a"] },
    });
    const only = routeTargets(deps, config, requestOf({ onlyChannel: "bark:b" }));
    expect(only.targets.map((routed) => routed.channelId)).toEqual(["bark:b"]);
    expect(only.stale).toEqual([]);

    const gone = routeTargets(deps, config, requestOf({ onlyChannel: "bark:gone" }));
    expect(gone.targets).toEqual([]);
    expect(gone.stale).toEqual([]);
  });

  // 停用被误报成「已删除」，用户一关频道就收到一串误导告警。
  it("stale 只报配置里根本不存在的频道；被停用的频道不误报", () => {
    const outcome = routeTargets(
      { frames: framePort().port, logger: makeLogger() },
      configAt({
        channels: [...builtins(), barkChannel({ id: "off", enabled: false })],
        kindRoutes: { done: ["bark:gone", "bark:off", "browser"] },
      }),
      requestOf(),
    );
    expect(outcome.stale).toEqual(["bark:gone"]);
    expect(outcome.targets.map((routed) => routed.channelId)).toEqual(["browser"]);
  });
});

describe("内置频道池：启用决定发不发，弹窗与声音决定怎么发", () => {
  // 弹窗关而声音开是合法组合（只响不弹），全关也是合法组合（这次什么都不发）：两者都只改变
  // 目标携带的配置，不改变「要不要投递」——判成出池会让出口连回答「没有可发的内容」的机会都没有。
  it("启用的内置频道恒进池：弹窗与声音只决定出口发什么，不决定发不发", () => {
    const deps = { frames: framePort().port, logger: makeLogger() };
    const soundOnly = routeTargets(
      deps,
      configAt({
        channels: builtins({
          browser: { popup: false, sound: "ding" },
          system: { popup: false, sound: false },
        }),
      }),
      requestOf(),
    );
    expect(soundOnly.targets.map((routed) => routed.channelId)).toEqual(["browser", "system"]);
    const browser = browserTargetOf(soundOnly, "browser");
    expect(browser.popup).toBe(false);
    expect(browser.sound).toBe("ding");

    // 全关（弹窗与声音都关）仍进池：出口据此回答 skipped，而不是被管线悄悄剔出去。
    const closed = routeTargets(
      deps,
      configAt({
        channels: builtins({
          browser: { popup: false, sound: false },
          system: { popup: false, sound: false },
        }),
      }),
      requestOf(),
    );
    expect(closed.targets.map((routed) => routed.channelId)).toEqual(["browser", "system"]);
    expect(browserTargetOf(closed, "browser").popup).toBe(false);
    expect(systemTargetOf(closed, "system").sound).toBe(false);
  });

  // 「发不发只看启用」：关掉启用之后，哪怕弹窗与声音都开着也不该有任何目标。这条与上一条一起
  // 把职责钉开——`enabled` 从池条件里删掉，这里的期望就会变成两个目标。
  it("渠道启用关掉即完全不投递：弹窗与声音开着也没有目标", () => {
    const deps = { frames: framePort().port, logger: makeLogger() };
    const browserOff = routeTargets(
      deps,
      configAt({
        channels: builtins({
          browser: { enabled: false, popup: true, sound: true },
          system: { enabled: true, popup: true, sound: true },
        }),
      }),
      requestOf(),
    );
    expect(browserOff.targets.map((routed) => routed.channelId)).toEqual(["system"]);

    const bothOff = routeTargets(
      deps,
      configAt({
        channels: builtins({
          browser: { enabled: false },
          system: { enabled: false },
        }),
      }),
      requestOf(),
    );
    expect(bothOff.targets).toEqual([]);
  });

  // popup 不是「有没有这个目标」，而是「弹不弹」：取反或写死一处，用户关掉弹窗后仍会被弹，
  // 而「只响不弹」这个组合也就退化成「什么都没配」。
  it("popup 跟随各自的弹窗开关：开关开才弹，只响不弹时两个内置出口都是 popup=false", () => {
    const deps = { frames: framePort().port, logger: makeLogger() };
    const bothOpen = routeTargets(
      deps,
      configAt({
        channels: builtins({
          browser: { popup: true, sound: false },
          system: { popup: true, sound: false },
        }),
      }),
      requestOf(),
    );
    expect(browserTargetOf(bothOpen, "browser").popup).toBe(true);
    expect(systemTargetOf(bothOpen, "system").popup).toBe(true);

    const soundOnly = routeTargets(
      deps,
      configAt({
        channels: builtins({
          browser: { popup: false, sound: "ding" },
          system: { popup: false, sound: "ding" },
        }),
      }),
      requestOf(),
    );
    expect(browserTargetOf(soundOnly, "browser").popup).toBe(false);
    expect(systemTargetOf(soundOnly, "system").popup).toBe(false);
  });

  // 帧里没有 kind，客户端只能给所有通知同一套图标与颜色；可见性漏带则「页面可见时也弹」失效。
  it("浏览器目标的帧出口带上本次 kind，可见性随目标进帧", () => {
    const { port, emitted } = framePort();
    const outcome = routeTargets(
      { frames: port, logger: makeLogger() },
      configAt({ channels: builtins({ browser: { whenVisible: true } }) }),
      requestOf({ kind: "error", title: "出错了", body: "细节" }),
    );
    const frame: NotifyFrame = {
      pop: true,
      sound: { mode: "silent" },
      whenVisible: true,
      title: "出错了",
      body: "细节",
    };
    browserTargetOf(outcome, "browser").emitFrame(frame);
    expect(emitted).toEqual([{ kind: "error", frame }]);
  });
});

describe("出站目标构造", () => {
  // 空串当配置带走会覆盖 bark 端的默认值；levels[kind] 不优先，紧急度就永远按 level 走。
  it("bark：levels[kind] 命中优先于 level；空串是没配置，badge 0 与正超时有值就带", () => {
    const deps = { frames: framePort().port, logger: makeLogger() };
    const channel = barkChannel({
      id: "a",
      level: "active",
      levels: { done: "critical" },
      group: "",
      icon: "",
      url: "",
      badge: 0,
      timeoutMs: 0,
    });
    const withChannel = (over: Partial<NotifyConfig> = {}) =>
      configAt({ channels: [...builtins(), channel], ...over });
    const done = barkTargetOf(routeTargets(deps, withChannel(), requestOf()), "bark:a");
    expect(done.level).toBe("critical");
    expect("group" in done).toBe(false);
    expect("icon" in done).toBe(false);
    expect("url" in done).toBe(false);
    expect(done.badge).toBe(0);
    expect("timeoutMs" in done).toBe(false);

    const other = barkTargetOf(
      routeTargets(deps, withChannel(), requestOf({ kind: "error" })),
      "bark:a",
    );
    expect(other.level).toBe("active");

    const timed = barkTargetOf(
      routeTargets(
        deps,
        configAt({ channels: [...builtins(), barkChannel({ id: "a", timeoutMs: 5000 })] }),
        requestOf(),
      ),
      "bark:a",
    );
    expect(timed.timeoutMs).toBe(5000);
  });

  // preset 缺省或 custom 映射错了，对端收到的就是另一种模板。
  it("webhook：preset 缺省回落 ntfy、custom 映射成 raw、空模板与 0 超时不带", () => {
    const deps = { frames: framePort().port, logger: makeLogger() };
    const bare = webhookTargetOf(
      routeTargets(deps, configAt({ channels: [...builtins(), webhookChannel()] }), requestOf()),
      "webhook:w",
    );
    expect(bare.preset).toBe("ntfy");
    expect("template" in bare).toBe(false);
    expect("headers" in bare).toBe(false);
    expect("timeoutSec" in bare).toBe(false);

    const custom = webhookTargetOf(
      routeTargets(
        deps,
        configAt({
          channels: [
            ...builtins(),
            webhookChannel({ preset: "custom", template: '{"a":1}', timeoutSec: 0 }),
          ],
        }),
        requestOf(),
      ),
      "webhook:w",
    );
    expect(custom.preset).toBe("raw");
    expect(custom.template).toBe('{"a":1}');
    expect("timeoutSec" in custom).toBe(false);

    // 空模板是「用预设默认模板」的表达，带进去对端会收到一个空 body。
    const emptyTemplate = webhookTargetOf(
      routeTargets(
        deps,
        configAt({ channels: [...builtins(), webhookChannel({ template: "" })] }),
        requestOf(),
      ),
      "webhook:w",
    );
    expect("template" in emptyTemplate).toBe(false);

    // 正超时必须带过去：不带就等于用户在设置页设的超时永远不生效（出口一律回落 10s）。
    const timed = webhookTargetOf(
      routeTargets(
        deps,
        configAt({ channels: [...builtins(), webhookChannel({ timeoutSec: 30 })] }),
        requestOf(),
      ),
      "webhook:w",
    );
    expect(timed.timeoutSec).toBe(30);
  });

  // 凭据空着却带上 auth 会发出一个「Bearer undefined」，none 却带凭据则是把凭据发给了不该收的端点。
  it("webhook 凭据：bearer/basic 出凭据对象，header 并入自定义头，空凭据与 none 都不给 auth", () => {
    const deps = { frames: framePort().port, logger: makeLogger() };
    const outcomeOf = (over: Partial<WebhookConfig>) =>
      webhookTargetOf(
        routeTargets(
          deps,
          configAt({ channels: [...builtins(), webhookChannel(over)] }),
          requestOf(),
        ),
        "webhook:w",
      );

    expect(outcomeOf({ auth: "bearer", token: "tk-1" }).auth).toEqual({
      kind: "bearer",
      token: "tk-1",
    });
    expect(outcomeOf({ auth: "basic", username: "user", password: "pass" }).auth).toEqual({
      kind: "basic",
      user: "user",
      password: "pass",
    });

    const header = outcomeOf({
      auth: "header",
      headerName: "X-Token",
      headerValue: "v-1",
      headers: { "x-extra": "1" },
    });
    expect(header.headers).toEqual({ "x-extra": "1", "X-Token": "v-1" });
    expect("auth" in header).toBe(false);

    expect("auth" in outcomeOf({ auth: "none" })).toBe(false);
    // 凭据字段空着时宁可没有 auth，也不发一个 "Bearer undefined" 出去。
    expect("auth" in outcomeOf({ auth: "bearer", token: "" })).toBe(false);
    // 字段整个缺席（不只是空串）也不能炸：脏配置不该把整条出站路由一起吃掉。
    expect("auth" in outcomeOf({ auth: "bearer" })).toBe(false);
    expect("auth" in outcomeOf({ auth: "basic" })).toBe(false);
    // header 认证两侧都非空才并入：空名会写出一个无名头，空值等于把对端原有的凭据清掉。
    expect("headers" in outcomeOf({ auth: "header", headerName: "X-Token", headerValue: "" })).toBe(
      false,
    );
    expect("headers" in outcomeOf({ auth: "header", headerName: "", headerValue: "v-1" })).toBe(
      false,
    );
    expect("headers" in outcomeOf({ auth: "header" })).toBe(false);
  });

  // 一个坏项吃掉整条通知，表现为「配置里加了个频道之后所有通知都没了」。
  it("频道读取 fail-soft：坏了一项只记 warn，已收进池的内置频道照常投", () => {
    const logger = makeLogger();
    const broken = {
      type: "bark",
      id: "bad",
      get enabled(): boolean {
        throw new Error("配置项损坏");
      },
    } as unknown as ChannelConfig;
    const outcome = routeTargets(
      { frames: framePort().port, logger },
      configAt({ channels: [...builtins(), broken] }),
      requestOf(),
    );
    expect(outcome.targets.map((routed) => routed.channelId)).toEqual(["browser", "system"]);
    expect(logger.warns).toHaveLength(1);
    expect(logger.warns[0]).toContain("频道读取失败");
  });
});

packages/dsh-notifier/test/unit/api/dry-.source:
/**
 * dsh-notifier api 域 probe 块 —— POST /test 的 dry-run 分支（提案 PR-B，症状1）。
 *
 * 判据面（B1/B2/B3/B5/B7）：draft 只认 channels（他键与 revision 忽略）；channelId 必填且须命中
 * 草稿条目；掩码按 id 还原（新频道/改名/跨 type 残留三路 400）；结果 B3 schema 且禁写面零调用
 * （submit / logger.warn 全程零次）；并发帽 2 超限 429 且 finally 释放；15s 总预算超时 408。
 * 出站一律经可注入的 dryRunTarget 桩或真实 browser 路径——无网络、无真实凭据（掩码即还原因子，
 * 真凭据只活在内存夹具里），无落盘（stores 入参结构上不存在，见禁写面用例）。
 */
import type { IncomingMessage } from "node:http";
import { afterEach, describe, expect, it, vi } from "vitest";

import type { ChannelPort, ConfigPort, PipelinePort } from "../../../src/server/api/deps.ts";
import { ProbeEndpoints } from "../../../src/server/api/impl/probe/index.ts";
import * as channelsApi from "../../../src/server/channels/interface.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import * as configApi from "../../../src/server/config/interface.ts";
import type { NotifyConfig, RawSettingValue } from "../../../src/server/config/impl/model/type.ts";
import * as pipelineApi from "../../../src/server/pipeline/interface.ts";
import type { DeliverResult } from "../../../src/server/channels/impl/deliver/type.ts";
import { DRY_RUN_BUDGET_MS } from "../../../src/server/api/impl/probe/dry-run/type.ts";
import { jsonReq, makeLogger, makeRes, settleMicrotasks } from "../../helpers.ts";

/** 掩码占位：独立抄写的跨端契约字面量（见 redact.test.ts 模块头）。 */
const MASK = "********";

/** 已存 bark 频道（含真凭据，只活在内存里）。 */
const STORED_BARK = {
  type: "bark",
  id: "bark-1",
  baseUrl: "https://api.day.app",
  deviceKey: "real-key",
  enabled: true,
};

/** 草稿 browser 频道（真实出站路径可达：browser 不走网络）。 */
const DRAFT_BROWSER = {
  type: "browser",
  id: "browser",
  enabled: true,
  popup: true,
  sound: false,
  whenVisible: false,
};

function channelsOf(...channels: unknown[]): NotifyConfig {
  return { ...DEFAULT_CONFIG, channels: channels as NotifyConfig["channels"] };
}

function fakeConfig(channels: unknown[]): ConfigPort {
  return {
    readConfig: () => channelsOf(...channels),
    readSettingsView: () => {
      throw new Error("dry-run 不读视图");
    },
    writeConfig: () => Promise.reject(new Error("dry-run 不写配置")),
    resolveDraftChannels: configApi.resolveDraftChannels,
    normalizeConfig: configApi.normalizeConfig,
  };
}

function fakePipeline(): PipelinePort & { submitted: unknown[] } {
  const submitted: unknown[] = [];
  return {
    submitted,
    submit: (request) => {
      submitted.push(request);
    },
    finalizeRequest: pipelineApi.finalizeRequest,
    barkTarget: pipelineApi.barkTarget,
    browserTarget: pipelineApi.browserTarget,
    systemTarget: pipelineApi.systemTarget,
    webhookTarget: pipelineApi.webhookTarget,
  };
}

function fakeChannels(over: Partial<ChannelPort> = {}): ChannelPort {
  return {
    probeCapabilities: () => Promise.reject(new Error("dry-run 不探测")),
    hostPlatform: () => "linux",
    undeterminedCapabilities: () => {
      throw new Error("dry-run 不兜底");
    },
    dryRunTarget: channelsApi.dryRunTarget,
    ...over,
  };
}

/** 常驻成功的出站桩（browser 真实路径之外，bark/webhook 必须走桩——无网络）。 */
function okRun(): ChannelPort["dryRunTarget"] {
  return () => Promise.resolve({ status: "ok", stage: "delivered" });
}

async function postTest(
  options: {
    pipeline?: PipelinePort & { submitted: unknown[] };
    channels?: ChannelPort;
    config?: ConfigPort;
    logger?: ReturnType<typeof makeLogger>;
    body?: unknown;
  } = {},
): Promise<{
  rec: { status: number };
  json: () => Record<string, unknown>;
  pipeline: { submitted: unknown[] };
  logger: { warns: string[] };
}> {
  const pipeline = options.pipeline ?? fakePipeline();
  const logger = options.logger ?? makeLogger();
  const config = options.config ?? fakeConfig([STORED_BARK]);
  const endpoints = new ProbeEndpoints(
    pipeline,
    options.channels ?? fakeChannels(),
    logger,
    config,
  );
  const req: IncomingMessage = jsonReq({
    method: "POST",
    url: "/api/dsh-notifier/test",
    body: options.body ?? {},
  });
  const { res, rec, json } = makeRes();
  // RouteHandler 回的是 void | Promise<void>：await 吃掉两种形态（本文件不断言返回体）。
  await endpoints.test(req, res);
  return { rec, json, pipeline, logger };
}

afterEach(() => {
  vi.useRealTimers();
  vi.unstubAllGlobals();
});

describe("POST /test dry-run：只认 channels（B1）", () => {
  it("顶层其它键与 revision 忽略：channels 合法即 200", async () => {
    const { rec, json } = await postTest({
      body: {
        channelId: "browser",
        draft: { channels: [DRAFT_BROWSER], revision: 99, kindRoutes: { x: ["y"] } },
      },
    });
    expect(rec.status).toBe(200);
    expect(json()).toEqual({ ok: true, channelId: "browser", status: "ok" });
  });

  it("draft 非对象 / channels 非数组 → 400（分支各钉 hint，非 any(String)）", async () => {
    for (const [draft, hint] of [
      [null, "draft 需要对象"],
      [{}, "draft.channels 需要数组"],
      [{ channels: "bark-1" }, "draft.channels 需要数组"],
    ] as const) {
      const { rec, json } = await postTest({ body: { channelId: "bark-1", draft } });
      expect(rec.status).toBe(400);
      expect(json()).toEqual({
        ok: false,
        error: { error: "草稿测试参数非法", details: expect.stringContaining(hint) },
      });
    }
  });

  it("单条非法即 400（bark 缺 deviceKey）", async () => {
    const bad = { type: "bark", id: "bark-1", baseUrl: "https://api.day.app", enabled: true };
    const { rec, json } = await postTest({
      body: { channelId: "bark-1", draft: { channels: [bad] } },
    });
    expect(rec.status).toBe(400);
    expect((json().error as { details: string }).details).toContain("缺少 deviceKey");
  });

  it("无 channelId 即 400（dry-run 只测单个频道）", async () => {
    const { rec } = await postTest({ body: { draft: { channels: [DRAFT_BROWSER] } } });
    expect(rec.status).toBe(400);
  });

  it("channelId 不在草稿里即 400", async () => {
    const { rec, json } = await postTest({
      body: { channelId: "bark:nope", draft: { channels: [DRAFT_BROWSER] } },
    });
    expect(rec.status).toBe(400);
    expect((json().error as { details: string }).details).toContain(
      "没有 channelId 对应的完整条目",
    );
  });

  it("单条实例草稿不带内置也放行（跳过 requireBuiltinsPresent）", async () => {
    const seen: string[] = [];
    const channels = fakeChannels({
      dryRunTarget: (target, message) => {
        seen.push(target.type + " " + JSON.stringify(message).length);
        return okRun()(target, message);
      },
    });
    const { rec, json } = await postTest({
      channels,
      body: { channelId: "bark:bark-1", draft: { channels: [STORED_BARK] } },
    });
    expect(rec.status).toBe(200);
    expect(json()).toEqual({ ok: true, channelId: "bark:bark-1", status: "ok" });
    expect(seen).toHaveLength(1);
  });
});

describe("POST /test dry-run：掩码往返（B2）", () => {
  it("掩码按 id 还原：出站拿到的是真凭据", async () => {
    const seen: unknown[] = [];
    const channels = fakeChannels({
      dryRunTarget: (target) => {
        seen.push(target);
        return okRun()(target, { title: "t", body: "b", kind: "test", ts: 1 });
      },
    });
    const draft = { ...STORED_BARK, deviceKey: MASK };
    const { rec } = await postTest({
      channels,
      body: { channelId: "bark:bark-1", draft: { channels: [draft] } },
    });
    expect(rec.status).toBe(200);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ type: "bark", deviceKey: "real-key" });
  });

  it("新频道无源带掩码 → 400", async () => {
    const draft = {
      type: "bark",
      id: "bark-new",
      baseUrl: "https://api.day.app",
      deviceKey: MASK,
      enabled: false,
    };
    const { rec, json } = await postTest({
      body: { channelId: "bark:bark-new", draft: { channels: [draft] } },
    });
    expect(rec.status).toBe(400);
    expect((json().error as { details: string }).details).toContain("新增频道不能提交掩码占位");
  });

  it("id 改名带掩码 → 400（原值按 id 对齐，改名即无源）", async () => {
    const draft = { ...STORED_BARK, id: "bark-renamed", deviceKey: MASK };
    const { rec, json } = await postTest({
      body: { channelId: "bark:bark-renamed", draft: { channels: [draft] } },
    });
    expect(rec.status).toBe(400);
    expect((json().error as { details: string }).details).toContain("新增频道不能提交掩码占位");
  });

  it("跨 type 残留掩码 → 400（bark→webhook 残留 deviceKey）", async () => {
    const stored = {
      type: "webhook",
      id: "webhook-1",
      url: "https://example.test/hook",
      auth: "none",
      enabled: true,
    };
    const draft = { ...stored, deviceKey: MASK };
    const { rec, json } = await postTest({
      config: fakeConfig([stored]),
      body: { channelId: "webhook:webhook-1", draft: { channels: [draft] } },
    });
    expect(rec.status).toBe(400);
    expect((json().error as { details: string }).details).toContain("未还原的掩码占位");
  });
});

describe("POST /test dry-run：结果 schema 与禁写面（B3）", () => {
  it("ok 结果恰为 {ok, channelId, status}（无 reason、无 sseConnections）", async () => {
    const writes: unknown[] = [];
    const config = fakeConfig([STORED_BARK]);
    const writeConfig = config.writeConfig;
    const spyConfig: ConfigPort = {
      ...config,
      writeConfig: ((patch: unknown, revision: unknown) => {
        writes.push([patch, revision]);
        return writeConfig(patch as never, revision as never);
      }) as ConfigPort["writeConfig"],
    };
    const { rec, json, pipeline, logger } = await postTest({
      config: spyConfig,
      body: { channelId: "browser", draft: { channels: [DRAFT_BROWSER] } },
    });
    expect(rec.status).toBe(200);
    expect(json()).toEqual({ ok: true, channelId: "browser", status: "ok" });
    expect(pipeline.submitted).toEqual([]);
    expect(logger.warns).toEqual([]);
    expect(writes).toEqual([]);
  });

  it("failed 结果原样收窄：code / params / detail 三段齐落（截断是出站契约，见 channels 层用例）", async () => {
    const channels = fakeChannels({
      dryRunTarget: () =>
        Promise.resolve({
          status: "failed",
          stage: "delivered",
          reason: { code: "reasonBarkHttp", params: { status: 500 }, detail: "short" },
          retryable: false,
        } as DeliverResult),
    });
    const logger = makeLogger();
    const { rec, json } = await postTest({
      channels,
      logger,
      body: { channelId: "browser", draft: { channels: [DRAFT_BROWSER] } },
    });
    expect(rec.status).toBe(200);
    expect(json()).toEqual({
      ok: true,
      channelId: "browser",
      status: "failed",
      reason: { code: "reasonBarkHttp", params: { status: 500 }, detail: "short" },
    });
    expect(logger.warns).toEqual([]);
  });

  it("skipped 结果同样同步返回（browser 双关经真实路径）", async () => {
    const off = { ...DRAFT_BROWSER, popup: false } as Record<string, RawSettingValue>;
    const { rec, json } = await postTest({
      body: { channelId: "browser", draft: { channels: [off] } },
    });
    expect(rec.status).toBe(200);
    expect(json()).toEqual({
      ok: true,
      channelId: "browser",
      status: "skipped",
      reason: { code: "reasonSkipConfig" },
    });
  });

  it("出站抛错即 500 固定文案且不记日志（禁写面含异常收口）", async () => {
    const channels = fakeChannels({
      dryRunTarget: () => Promise.reject(new Error("boom")),
    });
    const logger = makeLogger();
    const { rec, json, pipeline } = await postTest({
      channels,
      logger,
      body: { channelId: "browser", draft: { channels: [DRAFT_BROWSER] } },
    });
    expect(rec.status).toBe(500);
    expect(json()).toEqual({ ok: false, error: { error: "草稿测试内部错误" } });
    expect(pipeline.submitted).toEqual([]);
    expect(logger.warns).toEqual([]);
  });
});

describe("POST /test dry-run：BODY_LIMIT 16K（B5，与 settings 对齐）", () => {
  it("超限体 → 400 invalid-json（draft 再大也一样被挡在解析前）", async () => {
    const big = {
      channelId: "browser",
      draft: { channels: [DRAFT_BROWSER], pad: "p".repeat(20000) },
    };
    const { rec, json, pipeline } = await postTest({ body: big });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { code: "invalid-json", details: "请求体超出大小上限（16384 字节）" },
    });
    expect(pipeline.submitted).toEqual([]);
  });
});

describe("POST /test dry-run：并发帽与槽位释放（B5）", () => {
  it("同时 2 个在飞时第 3 个回 429 dry-run-busy；settle 后释放", async () => {
    let releaseFirst: () => void = () => {};
    let releaseSecond: () => void = () => {};
    const gate1 = new Promise<DeliverResult>((resolve) => {
      releaseFirst = () => resolve({ status: "ok", stage: "delivered" });
    });
    const gate2 = new Promise<DeliverResult>((resolve) => {
      releaseSecond = () => resolve({ status: "ok", stage: "delivered" });
    });
    const queue = [gate1, gate2];
    const channels = fakeChannels({ dryRunTarget: () => queue.shift() ?? gate1 });
    const pipeline = fakePipeline();
    const logger = makeLogger();
    const config = fakeConfig([DRAFT_BROWSER]);
    const endpoints = new ProbeEndpoints(pipeline, channels, logger, config);
    const call = async (draft: unknown) => {
      const req: IncomingMessage = jsonReq({
        method: "POST",
        url: "/api/dsh-notifier/test",
        body: { channelId: "browser", draft },
      });
      const slot = makeRes();
      await endpoints.test(req, slot.res);
      return slot;
    };
    const draft = { channels: [DRAFT_BROWSER] };
    const first = call(draft);
    const second = call(draft);
    // 前两次的占槽发生在 body 解析之后（多轮微任务）：排空队列而非只让出一拍，
    // 否则慢 runner 上第三次抢在占槽前，429 会误变成 200（时序假绿/假红）。
    await settleMicrotasks();
    await settleMicrotasks();
    const busy = await call(draft);
    expect(busy.rec.status).toBe(429);
    expect(busy.json()).toEqual({
      ok: false,
      error: {
        code: "dry-run-busy",
        error: "草稿测试并发已满，请稍后手动重试",
        details: "同时最多 2 个 dry-run（不排队）",
      },
    });
    releaseFirst();
    const settled = await first;
    expect(settled.rec.status).toBe(200);
    const retried = await call(draft);
    expect(retried.rec.status).toBe(200);
    releaseSecond();
    expect((await second).rec.status).toBe(200);
    expect(logger.warns).toEqual([]);
  });

  it("出站拒绝也释放槽位（finally 全路径）", async () => {
    const channels = fakeChannels({ dryRunTarget: () => Promise.reject(new Error("boom")) });
    const pipeline = fakePipeline();
    const config = fakeConfig([DRAFT_BROWSER]);
    const endpoints = new ProbeEndpoints(pipeline, channels, makeLogger(), config);
    const call = async () => {
      const req: IncomingMessage = jsonReq({
        method: "POST",
        url: "/api/dsh-notifier/test",
        body: { channelId: "browser", draft: { channels: [DRAFT_BROWSER] } },
      });
      const slot = makeRes();
      await endpoints.test(req, slot.res);
      return slot.rec.status;
    };
    expect(await call()).toBe(500);
    expect(await call()).toBe(500);
  });
});

describe("POST /test dry-run：总预算 15s（B7）", () => {
  it("15s 未 settle 即 408 dry-run-timeout，且超时释放槽位", async () => {
    expect(DRY_RUN_BUDGET_MS).toBe(15_000);
    vi.useFakeTimers();
    try {
      let calls = 0;
      const channels = fakeChannels({
        dryRunTarget: () => {
          calls += 1;
          if (calls === 1) return new Promise<DeliverResult>(() => {});
          return Promise.resolve({ status: "ok", stage: "delivered" });
        },
      });
      const pipeline = fakePipeline();
      const logger = makeLogger();
      const endpoints = new ProbeEndpoints(pipeline, channels, logger, fakeConfig([DRAFT_BROWSER]));
      const req: IncomingMessage = jsonReq({
        method: "POST",
        url: "/api/dsh-notifier/test",
        body: { channelId: "browser", draft: { channels: [DRAFT_BROWSER] } },
      });
      const slot = makeRes();
      const pending = endpoints.test(req, slot.res);
      await vi.advanceTimersByTimeAsync(15_000);
      await pending;
      expect(slot.rec.status).toBe(408);
      expect(slot.json()).toEqual({
        ok: false,
        error: {
          code: "dry-run-timeout",
          error: "草稿测试超时（15s），结果已丢弃",
          details: "在飞的投递无法撤回：若对方实际收到了，它不会出现在历史与状态里",
        },
      });
      expect(logger.warns).toEqual([]);
      // 超时同样走 finally：同一实例紧接着再打一次应直通（槽位已释放，不是 429）。
      // 第二次出站即时成功，无需再走 15s 预算（若槽位未释放，这里会是 429）。
      const retryReq: IncomingMessage = jsonReq({
        method: "POST",
        url: "/api/dsh-notifier/test",
        body: { channelId: "browser", draft: { channels: [DRAFT_BROWSER] } },
      });
      const retrySlot = makeRes();
      await endpoints.test(retryReq, retrySlot.res);
      expect(retrySlot.rec.status).toBe(200);
      expect(calls).toBe(2);
    } finally {
      vi.useRealTimers();
    }
  });
});

packages/dsh-notifier/test/unit/pipeline.source:
/**
 * dsh-notifier pipeline 域 service 块 —— 种类词汇表、装配面与归档。
 *
 * 判据为什么是这些：
 *  - 词汇表（`kinds.ts`）是裁决的坐标系：事件开关、`kindRoutes`、`allowKinds`、bark 紧急度全按它
 *    查，所以「内置 / 外部」的分界与强度的运行时白名单必须各自只有一份答案；
 *  - 装配面是单例：重复装配、卸载后仍收请求、卸载不清节奏状态，都是「上一个用例的状态漏进下一个」
 *    这类最难查的现场；
 *  - 归档是「为什么我没收到」的唯一答案来源，压制分支与发出分支都得留下记录。
 *
 * 装配纪律：`installPipeline` 是模块级单例，故每个用例后必须 `releasePipeline()`——否则下一个
 * `installPipeline` 当场抛「只能装配一次」，且逐频道节奏状态会跨用例延续。
 */
import { afterEach, describe, expect, it, vi } from "vitest";

import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import type { NotifyConfig } from "../../../src/server/config/impl/model/type.ts";
import type { DeliverReason } from "../../../src/server/shared/interface.ts";
import type {
  ChannelsPort,
  HistoryEntry,
  NotifyMessage,
  OutgoingFrame,
  PipelineDeps,
} from "../../../src/server/pipeline/deps.ts";
import {
  BUILTIN_KINDS,
  KIND_SEVERITY,
  NOTIFY_SEVERITIES,
  isBuiltinKind,
  isNotifySeverity,
} from "../../../src/server/pipeline/impl/service/kinds.ts";
import {
  installPipeline,
  releasePipeline,
  submit,
} from "../../../src/server/pipeline/interface.ts";
import type { NotifyRequest } from "../../../src/server/pipeline/interface.ts";
import { makeLogger, pollUntil, settleMicrotasks } from "../../helpers.ts";

/** 出站频道配置与帧载荷：经设置模型 / 域依赖声明可达，不必请别的块再导出一个名字。 */
type ChannelConfig = NotifyConfig["channels"][number];
type BarkConfig = Extract<ChannelConfig, { type: "bark" }>;

/** 装配面夹具：只伪 `pipeline/deps.ts` 声明的那几个端口，顺手记下四件观测物。 */
interface Harness {
  readonly deps: PipelineDeps;
  readonly history: HistoryEntry[];
  readonly statuses: Array<{
    channelId: string;
    status: "ok" | "failed";
    error: DeliverReason | undefined;
  }>;
  readonly delivered: Array<{ message: NotifyMessage; targets: readonly DeliveryTarget[] }>;
  readonly frames: OutgoingFrame[];
  readonly logger: ReturnType<typeof makeLogger>;
  /** 换掉这一刻生效的设置（设置是活的：装配期算出的快照会变成静态数据）。 */
  readonly useConfig: (patch?: Partial<NotifyConfig>) => void;
  /** 换掉投递出口的行为（缺省：全部送到）。 */
  readonly onDeliver: (deliver: ChannelsPort["deliver"]) => void;
}

type DeliveryTarget = Parameters<ChannelsPort["deliver"]>[1][number];

function configAt(patch: Partial<NotifyConfig> = {}): NotifyConfig {
  return { ...DEFAULT_CONFIG, ...patch };
}

function requestOf(over: Partial<NotifyRequest> = {}): NotifyRequest {
  return { kind: "done", title: "标题", body: "正文", ...over };
}

function barkChannel(over: Partial<BarkConfig> = {}): BarkConfig {
  return {
    type: "bark",
    id: "a",
    enabled: true,
    baseUrl: "http://127.0.0.1:40281/bark",
    deviceKey: "dk",
    ...over,
  };
}

/** 默认表里的内置频道：泛型只为把「按 type 找到的那条」收窄成对应型号——查找条件就是 type 相等。 */
function builtinOf<T extends "browser" | "system">(type: T): Extract<ChannelConfig, { type: T }> {
  const found = DEFAULT_CONFIG.channels.find((channel) => channel.type === type);
  if (found === undefined) throw new Error(`默认表里缺内置频道 ${type}`);
  return found as Extract<ChannelConfig, { type: T }>;
}

/**
 * 两条内置出口都停用：`channels` 是唯一关得掉它们的地方——顶层 `browserNotify` / `systemSound`
 * 一类键现在只是读面派生出来的只读投影，改它们不会让内置出口少投一次。
 */
function builtinsOff(): ChannelConfig[] {
  return [
    { ...builtinOf("browser"), enabled: false },
    { ...builtinOf("system"), enabled: false },
  ];
}

/** 只留 system 出口的设置：节流用例要「唯一目标」才数得清投递次数。 */
function systemOnly(patch: Partial<NotifyConfig> = {}): Partial<NotifyConfig> {
  return {
    // 内置两频道恒在 `channels` 里：停用 browser，只留 system（弹窗开、声音关，这一次有实际动作）。
    channels: [
      { ...builtinOf("browser"), enabled: false },
      { ...builtinOf("system"), enabled: true, popup: true, sound: false },
    ],
    ...patch,
  };
}

function assemble(over: Partial<PipelineDeps> = {}): Harness {
  const history: HistoryEntry[] = [];
  const statuses: Harness["statuses"][number][] = [];
  const delivered: Harness["delivered"][number][] = [];
  const frames: OutgoingFrame[] = [];
  const logger = makeLogger();
  const state: { config: NotifyConfig; deliver: ChannelsPort["deliver"] } = {
    config: DEFAULT_CONFIG,
    deliver: async (message, targets) => {
      delivered.push({ message, targets });
      return targets.map(() => ({ status: "ok", stage: "delivered" }));
    },
  };
  const deps: PipelineDeps = {
    enabled: true,
    frames: {
      emit: (payload) => {
        frames.push(payload);
      },
    },
    logger,
    config: { readConfig: () => state.config },
    stores: {
      appendHistory: (entry) => {
        history.push(entry);
      },
      recordStatus: (channelId, status, error) => {
        statuses.push({ channelId, status, error });
      },
    },
    channels: { deliver: (message, targets) => state.deliver(message, targets) },
    ...over,
  };
  installPipeline(deps);
  return {
    deps,
    history,
    statuses,
    delivered,
    frames,
    logger,
    useConfig: (patch = {}) => {
      state.config = configAt(patch);
    },
    onDeliver: (deliver) => {
      state.deliver = deliver;
    },
  };
}

afterEach(() => {
  releasePipeline();
  vi.useRealTimers();
});

describe("种类词汇表", () => {
  // 命名空间撞内置名被判成内置，等于绕过用户确认直接放行一条无归属的通知。
  it("isBuiltinKind 只认内置名；内置名一律不含冒号，与 `<命名空间>:<id>` 天然不相交", () => {
    for (const kind of BUILTIN_KINDS) {
      expect(isBuiltinKind(kind), kind).toBe(true);
    }
    // 撞上内置名的外部 kind 会被误判成内置，而误判方向恰好是「绕过用户确认直接放行」。
    for (const kind of ["ask:foo", "done:x", "ASK", "Ask", "ask ", " ask", "", "unknown"]) {
      expect(isBuiltinKind(kind), kind).toBe(false);
    }
    expect(BUILTIN_KINDS.filter((kind) => kind.includes(":"))).toEqual([]);
  });

  // 运行时白名单漏一档，合法强度会被静默判非法并回落缺省。
  it("强度白名单与值表互相覆盖：运行时白名单漏一档，合法强度会被静默判非法并回落缺省", () => {
    expect(NOTIFY_SEVERITIES).toEqual(["info", "success", "warning", "failure"]);
    for (const kind of BUILTIN_KINDS) {
      expect(NOTIFY_SEVERITIES, kind).toContain(KIND_SEVERITY[kind]);
    }
  });

  // 大小写或空白差异被放行，下游出口会拿到一个查不到映射的档位。
  it("isNotifySeverity 边界：大小写与未知档一律判非法（跨边界值不得被放行）", () => {
    for (const severity of NOTIFY_SEVERITIES) {
      expect(isNotifySeverity(severity), severity).toBe(true);
    }
    for (const value of ["", "Info", "INFO", "critical", " urgency", "info "]) {
      expect(isNotifySeverity(value), value).toBe(false);
    }
  });
});

describe("装配面：单例语义", () => {
  // 未装配时抛错会打断宿主事件链上别人的流程——本方法正是挂在事件链上的。
  it("未装配（或已卸载）时 submit 静默丢弃、release 幂等：宿主事件链上抛错会打断别人的流程", () => {
