describe("归档：发出与压制只在载荷上分叉", () => {
  // 压制不落史，用户问「为什么没收到」时没有任何可查的证据。
  it("总开关关：记 suppressed=disabled 且零投递（用户看不到通知时，历史里要有理由）", () => {
    const harness = assemble({ enabled: false });
    submit(requestOf());

    expect(harness.delivered).toEqual([]);
    expect(harness.history).toHaveLength(1);
    expect(harness.history[0]!.suppressed).toBe("disabled");
    expect(harness.history[0]!.channels).toBeUndefined();
  });

  // 频道全关是合法配置，把它记成发送成功会掩盖「一条都没发出去」。
  it("一个目标都没有：记 suppressed=no-target，而不是一条空的成功记录", () => {
    const harness = assemble();
    harness.useConfig({ channels: builtinsOff() });
    submit(requestOf());

    expect(harness.delivered).toEqual([]);
    expect(harness.history[0]!.suppressed).toBe("no-target");
  });

  // 两处各取一次时刻，就会出现「历史 12:00:00、收到的通知 12:00:01」。
  it("发出归档：投递载荷与历史记录共用同一个 ts，文案逐字一致", async () => {
    const harness = assemble();
    harness.useConfig({ channels: [...builtinsOff(), barkChannel()] });
    const before = Date.now();
    submit(requestOf({ title: "标题", body: "正文" }));
    await settleMicrotasks();
    const after = Date.now();

    const entry = harness.history[0]!;
    const message = harness.delivered[0]!.message;
    // 两处各取一次时刻是真实的回归形态：历史显示 12:00:00，收到的通知却是 12:00:01。
    expect(entry.ts).toBe(message.ts);
    expect(entry.ts).toBeGreaterThanOrEqual(before);
    expect(entry.ts).toBeLessThanOrEqual(after);
    expect(message.title).toBe("标题");
    expect(message.body).toBe("正文");
    expect(entry.title).toBe("标题");
    expect(entry.message).toBe("正文");
    expect(entry.kind).toBe("done");
  });

  // 日志口径与归档口径不同词，排查时「按日志找记录」这一步就对不上。
  it("kindRoutes 指向已删除频道：warn 与归档同一口径（suppressed:no-target），不静默也不自称 skipped", () => {
    const harness = assemble();
    harness.useConfig({ channels: builtinsOff(), kindRoutes: { done: ["bark:gone"] } });
    submit(requestOf());

    expect(harness.delivered).toEqual([]);
    const archived = harness.history[0]!.suppressed;
    expect(archived).toBe("no-target");
    expect(harness.logger.warns).toHaveLength(1);
    expect(harness.logger.warns[0]).toContain("kindRoutes[done]");
    expect(harness.logger.warns[0]).toContain("bark:gone");
    // 日志点名的那条口径就是历史里记下的那条：`SuppressReason` 里没有 skipped 这个词。
    expect(harness.logger.warns[0]).toContain(`suppressed:${archived}`);
    expect(harness.logger.warns[0]).not.toContain("skipped");
  });

  // 有别的目标时通知照常发出，此时谎称「本条按 suppressed 归档」会把排查引向一条不存在的记录。
  it("stale 但仍有其它目标：其余目标照常投递，warn 不谎称本条通知按 suppressed 归档", async () => {
    const harness = assemble();
    harness.useConfig({
      channels: [...builtinsOff(), barkChannel()],
      kindRoutes: { done: ["bark:gone", "bark:a"] },
    });
    submit(requestOf());
    await settleMicrotasks();

    expect(harness.history[0]!.channels).toEqual([{ channelId: "bark:a", status: "ok" }]);
    expect(harness.logger.warns).toHaveLength(1);
    expect(harness.logger.warns[0]).toContain("bark:gone");
    expect(harness.logger.warns[0]).not.toContain("suppressed:");
  });

  // 节奏状态跨装配期存活，会把上一次运行窗口的节流带进新一次装配。
  it("release 清空逐频道节奏状态：卸载再装配后同一频道重新计时，节流不跨装配期存活", async () => {
    const harness = assemble();
    harness.useConfig(systemOnly());
    vi.setSystemTime(new Date(2026, 0, 15, 12, 0, 0));

    submit(requestOf());
    await settleMicrotasks();
    expect(harness.delivered).toHaveLength(1);

    // 同一时刻的第二条：落在 system 出口的 1 秒节流窗口里，不产生第二次投递。
    submit(requestOf());
    await settleMicrotasks();
    expect(harness.delivered).toHaveLength(1);
    expect(harness.history).toHaveLength(2);

    releasePipeline();
    installPipeline(harness.deps);
    submit(requestOf());
    await settleMicrotasks();
    expect(harness.delivered).toHaveLength(2);
  });

  // 归档面违约发生在投递之后：不在这里收口，「通知发出去了但历史里没有」就只剩一个未捕获拒绝，
  // 而它挂在宿主事件链上，抛出去会打断别人的流程。
  it("归档面违约经「投递失败」告警收口：既不抛穿，也不静默（这是这条通知唯一的痕迹）", async () => {
    const logger = makeLogger();
    assemble({
      logger,
      stores: {
        appendHistory: () => {
          throw new Error("历史文件不可写");
        },
        recordStatus: () => {},
      },
    });

    submit(requestOf());
    await pollUntil(() => logger.warns.length === 1, "归档违约经日志收口");
    expect(logger.warns[0]).toContain("投递失败");
    expect(logger.warns[0]).toContain("历史文件不可写");
  });
});

/**
 * dsh-notifier pipeline 域 judge 块 —— 唯一裁决点的判据顺序与边界。
 *
 * 时间纪律：免打扰判定读 `new Date()`，故用 `vi.setSystemTime` 钉住「现在」。三点理由写在这里，
 * 因为这个文件是后续所有时间相关用例的样板：
 *  1. **不调 `vi.useFakeTimers`**：`setSystemTime` 单独用只换掉 `globalThis.Date`，不碰事件循环，
 *     因此与真实 IO 无冲突；开了假时钟就要跟着操心定时器推进。
 *  2. **日期一律本地构造** `new Date(y, m, d, h, mi)`：`getHours()/getMinutes()` 读的是本地时区，
 *     两端同源，于是本文件在任意 `TZ`、任意 pool（forks/threads）下结果一致；写成
 *     `new Date("...Z")` 会在非 UTC 时区下随机红。
 *  3. `afterEach` 必须 `useRealTimers()` 还原被替换的 `Date`，否则同文件后续用例看到伪造的「现在」。
 */
import { afterEach, describe, expect, it, vi } from "vitest";

import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import type { NotifyConfig } from "../../../src/server/config/impl/model/type.ts";
import { inWindow, judgeRequest } from "../../../src/server/pipeline/impl/judge/index.ts";
import { BUILTIN_KINDS } from "../../../src/server/pipeline/impl/service/kinds.ts";
import type { NotifyKind } from "../../../src/server/pipeline/impl/service/kinds.ts";
import type { NotifyRequest } from "../../../src/server/pipeline/impl/service/type.ts";

/** 事件开关在设置里的键名。 */
type KindSwitchKey =
  | "notifyAsk"
  | "notifyQuestion"
  | "notifyTaskDone"
  | "notifySubagentDone"
  | "notifyTaskError"
  | "notifyTurnEnd";

/** 内置事件 → 它的开关。独立写一遍而不是从源码导：漏配或改名的种类会在这里红，抄源码就恒真了。 */
const KIND_SWITCHES: ReadonlyArray<readonly [NotifyKind, KindSwitchKey]> = [
  ["ask", "notifyAsk"],
  ["question", "notifyQuestion"],
  ["done", "notifyTaskDone"],
  ["subagent-done", "notifySubagentDone"],
  ["error", "notifyTaskError"],
  ["turn-end", "notifyTurnEnd"],
];

/** 跨午夜窗口，用于免打扰与短路顺序两组用例。 */
const QUIET_CROSS_MIDNIGHT: NotifyConfig["quietHours"] = {
  enabled: true,
  windows: [{ start: "22:00", end: "08:00" }],
};

/** 2026-01-15 的某个本地时刻。 */
function at(hour: number, minute: number): Date {
  return new Date(2026, 0, 15, hour, minute, 0);
}

/** 把「现在」钉死并产出配置；`over` 只覆盖本次关心的键。 */
function configAt(now: Date, over: Partial<NotifyConfig> = {}): NotifyConfig {
  vi.setSystemTime(now);
  return { ...DEFAULT_CONFIG, ...over };
}

function request(kind: NotifyKind, over: Partial<NotifyRequest> = {}): NotifyRequest {
  return { kind, title: "标题", body: "正文", ...over };
}

afterEach(() => {
  vi.useRealTimers();
});

describe("judgeRequest 判据顺序：总开关 → kind 开关 → 动态 kind 确认 → 免打扰", () => {
  it("总开关关：短路在最前，连免打扰都不看", () => {
    const config = configAt(at(23, 0), { quietHours: QUIET_CROSS_MIDNIGHT });
    expect(judgeRequest(config, request("done"), false)).toEqual({ ok: false, reason: "disabled" });
  });

  it("kind 开关：六个内置事件各由自己的开关决定", () => {
    for (const [kind, key] of KIND_SWITCHES) {
      const off = configAt(at(12, 0));
      off[key] = false;
      expect(judgeRequest(off, request(kind), true), `${key} 关`).toEqual({
        ok: false,
        reason: "kind-off",
      });

      const on = configAt(at(12, 0));
      on[key] = true;
      expect(judgeRequest(on, request(kind), true), `${key} 开`).toEqual({ ok: true });
    }
  });

  it("内置种类开关覆盖完整：全部置关后除 test 外无一放行（漏配开关键的 kind 会在这里露出来）", () => {
    const allOff = configAt(at(12, 0));
    for (const [, key] of KIND_SWITCHES) allOff[key] = false;
    for (const kind of BUILTIN_KINDS) {
      if (kind === "test") continue;
      expect(judgeRequest(allOff, request(kind), true), kind).toEqual({
        ok: false,
        reason: "kind-off",
      });
    }
  });

  it("test 没有开关也没有免打扰：用户主动按下它，被静音吃掉等于测试按钮失效", () => {
    const config = configAt(at(23, 0), {
      notifyTaskDone: false,
      quietHours: { ...QUIET_CROSS_MIDNIGHT, allowKinds: [] },
    });
    expect(judgeRequest(config, request("test"), true)).toEqual({ ok: true });
  });

  it("kind 开关先于免打扰：开关关时给 kind-off 而不是 quiet", () => {
    const config = configAt(at(23, 0), { notifyTaskDone: false, quietHours: QUIET_CROSS_MIDNIGHT });
    expect(judgeRequest(config, request("done"), true)).toEqual({ ok: false, reason: "kind-off" });
  });

  it("severity 不参与裁决（只影响出站呈现）", () => {
    const config = configAt(at(12, 0));
    expect(judgeRequest(config, request("done", { severity: "failure" }), true)).toEqual({
      ok: true,
    });
  });
});

describe("judgeRequest 动态 kind：确认名单是唯一凭据", () => {
  it("未确认 → unlisted；确认（进 allowKinds）→ 放行", () => {
    expect(judgeRequest(configAt(at(12, 0)), request("demo:report"), true)).toEqual({
      ok: false,
      reason: "unlisted",
    });
    expect(
      judgeRequest(
        configAt(at(12, 0), { allowKinds: ["demo:report"] }),
        request("demo:report"),
        true,
      ),
    ).toEqual({ ok: true });
  });

  it("命名空间撞内置名的 kind 不是内置种类：allowKinds 里写 ask 不会放行 ask:foo", () => {
    // 与 sdk 域 send 守卫同源：`ask:foo` 查不到任何事件开关，放行它等于放行一条无归属的通知。
    const config = configAt(at(12, 0), { allowKinds: ["ask"] });
    expect(judgeRequest(config, request("ask:foo"), true)).toEqual({
      ok: false,
      reason: "unlisted",
    });
  });

  it("动态 kind 也受免打扰约束：确认与免打扰是两道独立的关", () => {
    const config = configAt(at(23, 0), {
      allowKinds: ["demo:report"],
      quietHours: QUIET_CROSS_MIDNIGHT,
    });
    expect(judgeRequest(config, request("demo:report"), true)).toEqual({
      ok: false,
      reason: "quiet",
    });
  });
});

describe("inWindow 纯函数：分钟级边界（不读当前时间，调用方只喂分钟数）", () => {
