    });
    expect(judgeRequest(config, request("error"), true)).toEqual({ ok: true });
    expect(judgeRequest(config, request("done"), true)).toEqual({ ok: false, reason: "quiet" });
  });

  it("脏设置不吞通知：时刻解析失败一律算未命中", () => {
    for (const [start, end] of [
      ["25:00", "08:00"],
      ["22:60", "08:00"],
      ["abc", "08:00"],
      ["", "08:00"],
      ["9:30", "08:00"],
